  1→package jlsm.memtable;
  2→
  3→import jlsm.core.memtable.MemTable;
  4→import jlsm.core.model.Entry;
  5→import jlsm.core.model.SequenceNumber;
  6→import jlsm.memtable.internal.CompositeKey;
  7→import jlsm.memtable.internal.KeyComparator;
  8→
  9→import java.lang.foreign.MemorySegment;
 10→import java.util.Iterator;
 11→import java.util.Map;
 12→import java.util.Objects;
 13→import java.util.Optional;
 14→import java.util.concurrent.ConcurrentSkipListMap;
 15→import java.util.concurrent.atomic.AtomicLong;
 16→
 17→/**
 18→ * A thread-safe {@link MemTable} backed by a {@link ConcurrentSkipListMap}.
 19→ *
 20→ * <p>
 21→ * Each entry is stored under a {@link CompositeKey} that combines the logical key with its sequence
 22→ * number. The {@link KeyComparator} orders entries ascending by logical key, and descending by
 23→ * sequence number within the same logical key, so the most recent version always appears first.
 24→ *
 25→ * <p>
 26→ * <b>Threading</b>: {@link ConcurrentSkipListMap} provides thread-safe concurrent reads and writes.
 27→ * Iterators are weakly consistent and may miss concurrent updates, which is acceptable for a
 28→ * MemTable.
 29→ */
 30→public final class ConcurrentSkipListMemTable implements MemTable {
 31→
 32→    /** Sentinel sequence number used as a probe in point lookups and range scans. */
 33→    private static final SequenceNumber PROBE_SEQ = new SequenceNumber(Long.MAX_VALUE);
 34→
 35→    private final ConcurrentSkipListMap<CompositeKey, Entry> map = new ConcurrentSkipListMap<>(
 36→            new KeyComparator());
 37→
 38→    private final AtomicLong sizeBytes = new AtomicLong(0L);
 39→
 40→    @Override
 41→    public void apply(Entry entry) {
 42→        Objects.requireNonNull(entry, "entry must not be null");
 43→
 44→        CompositeKey compositeKey = new CompositeKey(entry.key(), entry.sequenceNumber());
 45→        map.put(compositeKey, entry);
 46→
 47→        // Accumulate size estimate
 48→        long delta = switch (entry) {
 49→            case Entry.Put p -> p.key().byteSize() + p.value().byteSize() + Long.BYTES;
 50→            case Entry.Delete d -> d.key().byteSize() + Long.BYTES;
 51→        };
 52→        sizeBytes.addAndGet(delta);
 53→
 54→        assert map.containsKey(compositeKey) : "entry must be present after apply";
 55→    }
 56→
 57→    @Override
 58→    public Optional<Entry> get(MemorySegment key) {
 59→        Objects.requireNonNull(key, "key must not be null");
 60→
 61→        // Probe with Long.MAX_VALUE: sorts before all real entries for this key (seqnum descending)
 62→        CompositeKey probe = new CompositeKey(key, PROBE_SEQ);
 63→        Map.Entry<CompositeKey, Entry> ceiling = map.ceilingEntry(probe);
 64→
 65→        if (ceiling == null) {
 66→            return Optional.empty();
 67→        }
 68→
 69→        MemorySegment foundKey = ceiling.getKey().logicalKey();
 70→        if (foundKey.byteSize() != key.byteSize() || foundKey.mismatch(key) != -1L) {
 71→            // The ceiling entry belongs to a different logical key
 72→            return Optional.empty();
 73→        }
 74→
 75→        return Optional.of(ceiling.getValue());
 76→    }
 77→
 78→    @Override
 79→    public Iterator<Entry> scan() {
 80→        return map.values().iterator();
 81→    }
 82→
 83→    @Override
 84→    public Iterator<Entry> scan(MemorySegment fromKey, MemorySegment toKey) {
 85→        Objects.requireNonNull(fromKey, "fromKey must not be null");
 86→        Objects.requireNonNull(toKey, "toKey must not be null");
 87→
 88→        // fromBound (inclusive): Long.MAX_VALUE probe sorts before all real entries for fromKey
 89→        CompositeKey fromBound = new CompositeKey(fromKey, PROBE_SEQ);
 90→        // toBound (exclusive): Long.MAX_VALUE probe sorts before all real entries for toKey
 91→        CompositeKey toBound = new CompositeKey(toKey, PROBE_SEQ);
 92→
 93→        return map.subMap(fromBound, true, toBound, false).values().iterator();
 94→    }
 95→
 96→    @Override
 97→    public long approximateSizeBytes() {
 98→        return sizeBytes.get();
 99→    }
100→
101→    @Override
102→    public boolean isEmpty() {
103→        return map.isEmpty();
104→    }
105→}
