  1→package jlsm.sstable;
  2→
  3→import jlsm.bloom.blocked.BlockedBloomFilter;
  4→import jlsm.core.bloom.BloomFilter;
  5→import jlsm.core.model.Entry;
  6→import jlsm.core.model.Level;
  7→import jlsm.core.model.SequenceNumber;
  8→import jlsm.core.sstable.SSTableMetadata;
  9→import jlsm.core.sstable.SSTableWriter;
 10→import jlsm.sstable.internal.DataBlock;
 11→import jlsm.sstable.internal.EntryCodec;
 12→import jlsm.sstable.internal.SSTableFormat;
 13→
 14→import java.io.IOException;
 15→import java.lang.foreign.MemorySegment;
 16→import java.lang.foreign.ValueLayout;
 17→import java.nio.ByteBuffer;
 18→import java.nio.channels.FileChannel;
 19→import java.nio.channels.SeekableByteChannel;
 20→import java.nio.file.Files;
 21→import java.nio.file.Path;
 22→import java.nio.file.StandardOpenOption;
 23→import java.util.ArrayList;
 24→import java.util.List;
 25→import java.util.Objects;
 26→
 27→/**
 28→ * Writes entries to a new SSTable file using a trie-based key index.
 29→ *
 30→ * <p>
 31→ * State machine: {@code OPEN → FINISHED → CLOSED} and {@code OPEN → CLOSED}. Calling
 32→ * {@link #close()} without {@link #finish()} deletes the partial file.
 33→ */
 34→public final class TrieSSTableWriter implements SSTableWriter {
 35→
 36→    private enum State {
 37→        OPEN, FINISHED, CLOSED
 38→    }
 39→
 40→    private final long id;
 41→    private final Level level;
 42→    private final Path outputPath;
 43→    private final SeekableByteChannel channel;
 44→
 45→    // Data block accumulation
 46→    private DataBlock currentBlock = new DataBlock();
 47→    private long writePosition = 0L;
 48→
 49→    // Index: parallel lists of keys + file offsets (offset of entry start within the block data)
 50→    private final List<MemorySegment> indexKeys = new ArrayList<>();
 51→    private final List<Long> indexOffsets = new ArrayList<>();
 52→
 53→    // Bloom filter
 54→    private BloomFilter bloomFilter;
 55→    private final BloomFilter.Factory bloomFactory;
 56→
 57→    // Stats
 58→    private long entryCount = 0L;
 59→    private long approximateSizeBytes = 0L;
 60→    private MemorySegment smallestKey = null;
 61→    private MemorySegment largestKey = null;
 62→    private SequenceNumber minSequence = null;
 63→    private SequenceNumber maxSequence = null;
 64→
 65→    // Previous key for ordering check
 66→    private byte[] lastKeyBytes = null;
 67→
 68→    private State state = State.OPEN;
 69→
 70→    /**
 71→     * Creates a new writer that will write to {@code outputPath} using a {@link BlockedBloomFilter}
 72→     * with 1% target false-positive rate.
 73→     *
 74→     * @param id unique SSTable identifier
 75→     * @param level LSM level for this SSTable
 76→     * @param outputPath path to the output file; must not exist
 77→     * @throws IOException if the file cannot be opened
 78→     */
 79→    public TrieSSTableWriter(long id, Level level, Path outputPath) throws IOException {
 80→        this(id, level, outputPath, n -> new BlockedBloomFilter(n, 0.01));
 81→    }
 82→
 83→    /**
 84→     * Creates a new writer that will write to {@code outputPath} using a custom bloom filter
 85→     * factory. The factory is invoked at {@link #finish()} time with the actual entry count.
 86→     *
 87→     * @param id unique SSTable identifier
 88→     * @param level LSM level for this SSTable
 89→     * @param outputPath path to the output file; must not exist
 90→     * @param bloomFactory factory used to create the bloom filter; must not be null
 91→     * @throws IOException if the file cannot be opened
 92→     */
 93→    public TrieSSTableWriter(long id, Level level, Path outputPath,
 94→            BloomFilter.Factory bloomFactory) throws IOException {
 95→        Objects.requireNonNull(level, "level must not be null");
 96→        Objects.requireNonNull(outputPath, "outputPath must not be null");
 97→        Objects.requireNonNull(bloomFactory, "bloomFactory must not be null");
 98→        this.id = id;
 99→        this.level = level;
100→        this.outputPath = outputPath;
101→        this.bloomFactory = bloomFactory;
102→        this.channel = Files.newByteChannel(outputPath, StandardOpenOption.CREATE_NEW,
103→                StandardOpenOption.WRITE);
104→    }
105→
106→    @Override
107→    public void append(Entry entry) throws IOException {
108→        Objects.requireNonNull(entry, "entry must not be null");
109→        if (state != State.OPEN) {
110→            throw new IllegalStateException("writer is not open (state=" + state + ")");
111→        }
112→
113→        byte[] keyBytes = entry.key().toArray(ValueLayout.JAVA_BYTE);
114→
115→        // Enforce strictly ascending key order
116→        if (lastKeyBytes != null) {
117→            int cmp = compareUnsigned(keyBytes, lastKeyBytes);
118→            if (cmp <= 0) {
119→                throw new IllegalArgumentException(
120→                        "keys must be strictly ascending; got key not greater than previous key");
121→            }
122→        }
123→
124→        byte[] encoded = EntryCodec.encode(entry);
125→
126→        // Absolute file offset of this entry: block start + block's current byte size.
127→        // currentBlock.byteSize() includes the 4-byte count header plus all previously encoded
128→        // entries, so this points to the byte immediately after the last written entry.
129→        long entryAbsOffset = writePosition + currentBlock.byteSize();
130→
131→        indexKeys.add(MemorySegment.ofArray(keyBytes));
132→        indexOffsets.add(entryAbsOffset);
133→
134→        currentBlock.add(encoded);
135→        approximateSizeBytes += encoded.length;
136→
137→        // Update stats
138→        SequenceNumber seq = entry.sequenceNumber();
139→        if (smallestKey == null)
140→            smallestKey = MemorySegment.ofArray(keyBytes.clone());
141→        largestKey = MemorySegment.ofArray(keyBytes.clone());
142→
143→        if (minSequence == null || seq.compareTo(minSequence) < 0)
144→            minSequence = seq;
145→        if (maxSequence == null || seq.compareTo(maxSequence) > 0)
146→            maxSequence = seq;
147→
148→        lastKeyBytes = keyBytes;
149→        entryCount++;
150→
151→        // Flush block if it exceeds the target size
152→        if (currentBlock.byteSize() >= SSTableFormat.DEFAULT_BLOCK_SIZE) {
153→            flushCurrentBlock();
154→        }
155→    }
156→
157→    private void flushCurrentBlock() throws IOException {
158→        if (currentBlock.count() == 0)
159→            return;
160→        byte[] blockBytes = currentBlock.serialize();
161→        writeBytes(blockBytes);
162→        currentBlock = new DataBlock();
163→    }
164→
165→    private void writeBytes(byte[] bytes) throws IOException {
166→        ByteBuffer buf = ByteBuffer.wrap(bytes);
167→        while (buf.hasRemaining()) {
168→            channel.write(buf);
169→        }
170→        writePosition += bytes.length;
171→    }
172→
173→    @Override
174→    public SSTableMetadata finish() throws IOException {
175→        if (state != State.OPEN) {
176→            throw new IllegalStateException("finish() already called or writer is closed");
177→        }
178→        if (entryCount == 0) {
179→            throw new IllegalStateException("cannot finish an empty SSTable");
180→        }
181→
182→        // Flush remaining block
183→        flushCurrentBlock();
184→
185→        // Build bloom filter
186→        bloomFilter = bloomFactory.create((int) Math.max(1, entryCount));
187→        for (MemorySegment key : indexKeys) {
188→            bloomFilter.add(key);
189→        }
190→
191→        // Write key index
192→        long indexOffset = writePosition;
193→        writeKeyIndex();
194→        long indexLength = writePosition - indexOffset;
195→
196→        // Write bloom filter
197→        long filterOffset = writePosition;
198→        MemorySegment filterBytes = bloomFilter.serialize();
199→        byte[] filterArray = filterBytes.toArray(ValueLayout.JAVA_BYTE);
200→        writeBytes(filterArray);
201→        long filterLength = writePosition - filterOffset;
202→
203→        // Write footer
204→        writeFooter(indexOffset, indexLength, filterOffset, filterLength);
205→
206→        // fsync if supported (e.g., local FileChannel; skipped for object-storage channels)
207→        if (channel instanceof FileChannel fc)
208→            fc.force(true);
209→
210→        long sizeBytes = writePosition;
211→
212→        state = State.FINISHED;
213→
214→        return new SSTableMetadata(id, outputPath, level, smallestKey, largestKey, minSequence,
215→                maxSequence, sizeBytes, entryCount);
216→    }
217→
218→    private void writeKeyIndex() throws IOException {
219→        int numKeys = indexKeys.size();
220→        // count: 4 bytes
221→        // per key: 4 (keyLen) + keyBytes + 8 (offset)
222→        int indexSize = 4;
223→        for (MemorySegment k : indexKeys) {
224→            indexSize += 4 + (int) k.byteSize() + 8;
225→        }
226→        byte[] buf = new byte[indexSize];
227→        int off = 0;
228→        // numKeys
229→        buf[off++] = (byte) (numKeys >>> 24);
230→        buf[off++] = (byte) (numKeys >>> 16);
231→        buf[off++] = (byte) (numKeys >>> 8);
232→        buf[off++] = (byte) numKeys;
233→
234→        for (int i = 0; i < numKeys; i++) {
235→            byte[] keyBytes = indexKeys.get(i).toArray(ValueLayout.JAVA_BYTE);
236→            int keyLen = keyBytes.length;
237→            buf[off++] = (byte) (keyLen >>> 24);
238→            buf[off++] = (byte) (keyLen >>> 16);
239→            buf[off++] = (byte) (keyLen >>> 8);
240→            buf[off++] = (byte) keyLen;
241→            System.arraycopy(keyBytes, 0, buf, off, keyLen);
242→            off += keyLen;
243→            long fileOff = indexOffsets.get(i);
244→            buf[off++] = (byte) (fileOff >>> 56);
245→            buf[off++] = (byte) (fileOff >>> 48);
246→            buf[off++] = (byte) (fileOff >>> 40);
247→            buf[off++] = (byte) (fileOff >>> 32);
248→            buf[off++] = (byte) (fileOff >>> 24);
249→            buf[off++] = (byte) (fileOff >>> 16);
250→            buf[off++] = (byte) (fileOff >>> 8);
251→            buf[off++] = (byte) fileOff;
252→        }
253→        writeBytes(buf);
254→    }
255→
256→    private void writeFooter(long idxOffset, long idxLength, long fltOffset, long fltLength)
257→            throws IOException {
258→        byte[] buf = new byte[SSTableFormat.FOOTER_SIZE];
259→        int off = 0;
260→        off = writeLong(buf, off, idxOffset);
261→        off = writeLong(buf, off, idxLength);
262→        off = writeLong(buf, off, fltOffset);
263→        off = writeLong(buf, off, fltLength);
264→        off = writeLong(buf, off, entryCount);
265→        writeLong(buf, off, SSTableFormat.MAGIC);
266→        writeBytes(buf);
267→    }
268→
269→    private static int writeLong(byte[] buf, int off, long v) {
270→        buf[off++] = (byte) (v >>> 56);
271→        buf[off++] = (byte) (v >>> 48);
272→        buf[off++] = (byte) (v >>> 40);
273→        buf[off++] = (byte) (v >>> 32);
274→        buf[off++] = (byte) (v >>> 24);
275→        buf[off++] = (byte) (v >>> 16);
276→        buf[off++] = (byte) (v >>> 8);
277→        buf[off++] = (byte) v;
278→        return off;
279→    }
280→
281→    @Override
282→    public long entryCount() {
283→        return entryCount;
284→    }
285→
286→    @Override
287→    public long approximateSizeBytes() {
288→        return approximateSizeBytes;
289→    }
290→
291→    @Override
292→    public void close() throws IOException {
293→        if (state == State.CLOSED)
294→            return;
295→        boolean shouldDelete = (state == State.OPEN);
296→        state = State.CLOSED;
297→        IOException channelEx = null;
298→        try {
299→            channel.close();
300→        } catch (IOException e) {
301→            channelEx = e;
302→        } finally {
303→            if (shouldDelete) {
304→                try {
305→                    Files.deleteIfExists(outputPath);
306→                } catch (IOException deleteEx) {
307→                    if (channelEx != null) {
308→                        channelEx.addSuppressed(deleteEx);
309→                    } else {
310→                        channelEx = deleteEx;
311→                    }
312→                }
313→            }
314→        }
315→        if (channelEx != null)
316→            throw channelEx;
317→    }
318→
319→    private static int compareUnsigned(byte[] a, byte[] b) {
320→        int len = Math.min(a.length, b.length);
321→        for (int i = 0; i < len; i++) {
322→            int cmp = Byte.compareUnsigned(a[i], b[i]);
323→            if (cmp != 0)
324→                return cmp;
325→        }
326→        return Integer.compare(a.length, b.length);
327→    }
328→}
