  1→package jlsm.sstable;
  2→
  3→import jlsm.core.bloom.BloomFilter;
  4→import jlsm.core.cache.BlockCache;
  5→import jlsm.core.model.Entry;
  6→import jlsm.core.model.Level;
  7→import jlsm.core.model.SequenceNumber;
  8→import jlsm.core.sstable.SSTableMetadata;
  9→import jlsm.core.sstable.SSTableReader;
 10→import jlsm.sstable.internal.EntryCodec;
 11→import jlsm.sstable.internal.KeyIndex;
 12→import jlsm.sstable.internal.SSTableFormat;
 13→
 14→import java.io.IOException;
 15→import java.io.UncheckedIOException;
 16→import java.lang.foreign.Arena;
 17→import java.lang.foreign.MemorySegment;
 18→import java.lang.foreign.ValueLayout;
 19→import java.nio.ByteBuffer;
 20→import java.nio.channels.SeekableByteChannel;
 21→import java.nio.file.Files;
 22→import java.nio.file.Path;
 23→import java.nio.file.StandardOpenOption;
 24→import java.util.ArrayList;
 25→import java.util.Iterator;
 26→import java.util.List;
 27→import java.util.NoSuchElementException;
 28→import java.util.Objects;
 29→import java.util.Optional;
 30→
 31→/**
 32→ * Reads an SSTable file written by {@link TrieSSTableWriter}.
 33→ *
 34→ * <p>
 35→ * Two factory methods:
 36→ * <ul>
 37→ * <li>{@link #open} — eager: loads the entire data region into memory on open</li>
 38→ * <li>{@link #openLazy} — lazy: loads only footer, key index, bloom filter; reads data on
 39→ * demand</li>
 40→ * </ul>
 41→ */
 42→public final class TrieSSTableReader implements SSTableReader {
 43→
 44→    private final SSTableMetadata metadata;
 45→    private final KeyIndex keyIndex;
 46→    private final BloomFilter bloomFilter;
 47→    private final long dataEnd; // file offset just past the last data block (= index start)
 48→
 49→    // Eager mode: all data bytes pre-loaded; lazy mode: null
 50→    private final byte[] eagerData;
 51→
 52→    // Lazy mode: open channel; eager mode: null
 53→    private final SeekableByteChannel lazyChannel;
 54→
 55→    // Optional block cache; null means no caching
 56→    private final BlockCache blockCache;
 57→
 58→    private volatile boolean closed = false;
 59→
 60→    private TrieSSTableReader(SSTableMetadata metadata, KeyIndex keyIndex, BloomFilter bloomFilter,
 61→            long dataEnd, byte[] eagerData, SeekableByteChannel lazyChannel,
 62→            BlockCache blockCache) {
 63→        this.metadata = metadata;
 64→        this.keyIndex = keyIndex;
 65→        this.bloomFilter = bloomFilter;
 66→        this.dataEnd = dataEnd;
 67→        this.eagerData = eagerData;
 68→        this.lazyChannel = lazyChannel;
 69→        this.blockCache = blockCache;
 70→    }
 71→
 72→    // ---- Factory methods ----
 73→
 74→    public static TrieSSTableReader open(Path path, BloomFilter.Deserializer bloomDeserializer)
 75→            throws IOException {
 76→        return open(path, bloomDeserializer, null);
 77→    }
 78→
 79→    public static TrieSSTableReader open(Path path, BloomFilter.Deserializer bloomDeserializer,
 80→            BlockCache blockCache) throws IOException {
 81→        Objects.requireNonNull(path, "path must not be null");
 82→        Objects.requireNonNull(bloomDeserializer, "bloomDeserializer must not be null");
 83→
 84→        SeekableByteChannel ch = Files.newByteChannel(path, StandardOpenOption.READ);
 85→        try {
 86→            long fileSize = ch.size();
 87→            Footer footer = readFooter(ch, fileSize);
 88→            KeyIndex keyIndex = readKeyIndex(ch, footer);
 89→            BloomFilter bloom = readBloomFilter(ch, footer, bloomDeserializer);
 90→            SSTableMetadata meta = buildMetadata(path, fileSize, footer, keyIndex);
 91→
 92→            // Read entire data region eagerly
 93→            int dataLen = (int) footer.idxOffset;
 94→            byte[] data = readBytes(ch, 0L, dataLen);
 95→            ch.close();
 96→
 97→            return new TrieSSTableReader(meta, keyIndex, bloom, footer.idxOffset, data, null,
 98→                    blockCache);
 99→        } catch (IOException e) {
100→            ch.close();
101→            throw e;
102→        }
103→    }
104→
105→    public static TrieSSTableReader openLazy(Path path, BloomFilter.Deserializer bloomDeserializer)
106→            throws IOException {
107→        return openLazy(path, bloomDeserializer, null);
108→    }
109→
110→    public static TrieSSTableReader openLazy(Path path, BloomFilter.Deserializer bloomDeserializer,
111→            BlockCache blockCache) throws IOException {
112→        Objects.requireNonNull(path, "path must not be null");
113→        Objects.requireNonNull(bloomDeserializer, "bloomDeserializer must not be null");
114→
115→        SeekableByteChannel ch = Files.newByteChannel(path, StandardOpenOption.READ);
116→        try {
117→            long fileSize = ch.size();
118→            Footer footer = readFooter(ch, fileSize);
119→            KeyIndex keyIndex = readKeyIndex(ch, footer);
120→            BloomFilter bloom = readBloomFilter(ch, footer, bloomDeserializer);
121→            SSTableMetadata meta = buildMetadata(path, fileSize, footer, keyIndex);
122→
123→            return new TrieSSTableReader(meta, keyIndex, bloom, footer.idxOffset, null, ch,
124→                    blockCache);
125→        } catch (IOException e) {
126→            ch.close();
127→            throw e;
128→        }
129→    }
130→
131→    // ---- SSTableReader interface ----
132→
133→    @Override
134→    public SSTableMetadata metadata() {
135→        return metadata;
136→    }
137→
138→    @Override
139→    public Optional<Entry> get(MemorySegment key) throws IOException {
140→        Objects.requireNonNull(key, "key must not be null");
141→        checkNotClosed();
142→
143→        if (!bloomFilter.mightContain(key)) {
144→            return Optional.empty();
145→        }
146→
147→        Optional<Long> fileOffsetOpt = keyIndex.lookup(key);
148→        if (fileOffsetOpt.isEmpty()) {
149→            return Optional.empty();
150→        }
151→
152→        long fileOffset = fileOffsetOpt.get();
153→        byte[] entryBytes = readDataAt(fileOffset, SSTableFormat.DEFAULT_BLOCK_SIZE);
154→        // entryBytes starts at fileOffset, so the entry is at index 0
155→        return Optional.of(EntryCodec.decode(entryBytes, 0));
156→    }
157→
158→    @Override
159→    public Iterator<Entry> scan() throws IOException {
160→        checkNotClosed();
161→        byte[] data = getAllData();
162→        return new DataRegionIterator(data, dataEnd);
163→    }
164→
165→    @Override
166→    public Iterator<Entry> scan(MemorySegment fromKey, MemorySegment toKey) throws IOException {
167→        Objects.requireNonNull(fromKey, "fromKey must not be null");
168→        Objects.requireNonNull(toKey, "toKey must not be null");
169→        checkNotClosed();
170→        return new IndexRangeIterator(keyIndex.rangeIterator(fromKey, toKey));
171→    }
172→
173→    @Override
174→    public void close() throws IOException {
175→        if (closed)
176→            return;
177→        closed = true;
178→        if (lazyChannel != null) {
179→            lazyChannel.close();
180→        }
181→    }
182→
183→    // ---- Internal helpers ----
184→
185→    private void checkNotClosed() throws IOException {
186→        if (closed)
187→            throw new IllegalStateException("reader is closed");
188→    }
189→
190→    /** Returns the data at {@code fileOffset}, reading at most {@code maxBytes} bytes. */
191→    private byte[] readDataAt(long fileOffset, int maxBytes) throws IOException {
192→        int len = (int) Math.min(maxBytes, dataEnd - fileOffset);
193→        if (len <= 0)
194→            throw new IOException("file offset out of data range: " + fileOffset);
195→
196→        if (blockCache != null) {
197→            Optional<MemorySegment> hit = blockCache.get(metadata.id(), fileOffset);
198→            if (hit.isPresent()) {
199→                return hit.get().toArray(ValueLayout.JAVA_BYTE);
200→            }
201→        }
202→
203→        byte[] data;
204→        if (eagerData != null) {
205→            data = new byte[len];
206→            System.arraycopy(eagerData, (int) fileOffset, data, 0, len);
207→        } else {
208→            data = readBytes(lazyChannel, fileOffset, len);
209→        }
210→
211→        if (blockCache != null) {
212→            blockCache.put(metadata.id(), fileOffset, MemorySegment.ofArray(data));
213→        }
214→        return data;
215→    }
216→
217→    /** Returns the full data region (for full scan). */
218→    private byte[] getAllData() throws IOException {
219→        if (eagerData != null)
220→            return eagerData;
221→        return readBytes(lazyChannel, 0L, (int) dataEnd);
222→    }
223→
224→    // ---- Footer / index / filter loading ----
225→
226→    private record Footer(long idxOffset, long idxLength, long fltOffset, long fltLength,
227→            long entryCount) {
228→    }
229→
230→    private static Footer readFooter(SeekableByteChannel ch, long fileSize) throws IOException {
231→        if (fileSize < SSTableFormat.FOOTER_SIZE) {
232→            throw new IOException("not a valid SSTable file: too small");
233→        }
234→        byte[] buf = readBytes(ch, fileSize - SSTableFormat.FOOTER_SIZE, SSTableFormat.FOOTER_SIZE);
235→        long idxOffset = readLong(buf, 0);
236→        long idxLength = readLong(buf, 8);
237→        long fltOffset = readLong(buf, 16);
238→        long fltLength = readLong(buf, 24);
239→        long entryCount = readLong(buf, 32);
240→        long magic = readLong(buf, 40);
241→        if (magic != SSTableFormat.MAGIC) {
242→            throw new IOException("not a valid SSTable file: bad magic " + Long.toHexString(magic));
243→        }
244→        return new Footer(idxOffset, idxLength, fltOffset, fltLength, entryCount);
245→    }
246→
247→    private static KeyIndex readKeyIndex(SeekableByteChannel ch, Footer footer) throws IOException {
248→        byte[] buf = readBytes(ch, footer.idxOffset, (int) footer.idxLength);
249→        int numKeys = readInt(buf, 0);
250→        List<MemorySegment> keys = new ArrayList<>(numKeys);
251→        List<Long> offsets = new ArrayList<>(numKeys);
252→        int off = 4;
253→        for (int i = 0; i < numKeys; i++) {
254→            int keyLen = readInt(buf, off);
255→            off += 4;
256→            byte[] keyBytes = new byte[keyLen];
257→            System.arraycopy(buf, off, keyBytes, 0, keyLen);
258→            off += keyLen;
259→            long fileOffset = readLong(buf, off);
260→            off += 8;
261→            keys.add(MemorySegment.ofArray(keyBytes));
262→            offsets.add(fileOffset);
263→        }
264→        return new KeyIndex(keys, offsets);
265→    }
266→
267→    private static BloomFilter readBloomFilter(SeekableByteChannel ch, Footer footer,
268→            BloomFilter.Deserializer deserializer) throws IOException {
269→        byte[] buf = readBytes(ch, footer.fltOffset, (int) footer.fltLength);
270→        // Use an Arena-allocated segment to satisfy the alignment constraints of the deserializer
271→        // (BlockedBloomFilter uses JAVA_INT/JAVA_LONG without withByteAlignment(1)).
272→        try (Arena arena = Arena.ofShared()) {
273→            MemorySegment seg = arena.allocate(buf.length, 8);
274→            MemorySegment.copy(MemorySegment.ofArray(buf), 0, seg, 0, buf.length);
275→            return deserializer.deserialize(seg);
276→        }
277→    }
278→
279→    private static SSTableMetadata buildMetadata(Path path, long fileSize, Footer footer,
280→            KeyIndex keyIndex) {
281→        MemorySegment smallestKey = null;
282→        MemorySegment largestKey = null;
283→        Iterator<KeyIndex.Entry> it = keyIndex.iterator();
284→        while (it.hasNext()) {
285→            KeyIndex.Entry e = it.next();
286→            if (smallestKey == null)
287→                smallestKey = e.key();
288→            largestKey = e.key();
289→        }
290→        assert smallestKey != null : "key index must not be empty when building metadata";
291→        return new SSTableMetadata(0L, path, Level.L0, smallestKey, largestKey, SequenceNumber.ZERO,
292→                SequenceNumber.ZERO, fileSize, footer.entryCount);
293→    }
294→
295→    // ---- Low-level I/O ----
296→
297→    private static byte[] readBytes(SeekableByteChannel ch, long offset, int length)
298→            throws IOException {
299→        if (length == 0)
300→            return new byte[0];
301→        ByteBuffer buf = ByteBuffer.allocate(length);
302→        ch.position(offset);
303→        while (buf.hasRemaining()) {
304→            int read = ch.read(buf);
305→            if (read < 0)
306→                throw new IOException("unexpected EOF at offset " + (offset + buf.position()));
307→        }
308→        return buf.array();
309→    }
310→
311→    private static int readInt(byte[] buf, int off) {
312→        return ((buf[off] & 0xFF) << 24) | ((buf[off + 1] & 0xFF) << 16)
313→                | ((buf[off + 2] & 0xFF) << 8) | (buf[off + 3] & 0xFF);
314→    }
315→
316→    private static long readLong(byte[] buf, int off) {
317→        return ((long) (buf[off] & 0xFF) << 56) | ((long) (buf[off + 1] & 0xFF) << 48)
318→                | ((long) (buf[off + 2] & 0xFF) << 40) | ((long) (buf[off + 3] & 0xFF) << 32)
319→                | ((long) (buf[off + 4] & 0xFF) << 24) | ((long) (buf[off + 5] & 0xFF) << 16)
320→                | ((long) (buf[off + 6] & 0xFF) << 8) | (long) (buf[off + 7] & 0xFF);
321→    }
322→
323→    // ---- Iterators ----
324→
325→    /**
326→     * Iterates entries by parsing the raw data region linearly (block by block). Parses: [int
327→     * count][entry...][int count][entry...]... until offset reaches dataEnd.
328→     */
329→    private static final class DataRegionIterator implements Iterator<Entry> {
330→        private final byte[] data;
331→        private final long dataEnd;
332→        private int offset = 0;
333→        private List<Entry> blockEntries = new ArrayList<>();
334→        private int entryIdx = 0;
335→        private Entry next;
336→
337→        DataRegionIterator(byte[] data, long dataEnd) {
338→            this.data = data;
339→            this.dataEnd = dataEnd;
340→            advance();
341→        }
342→
343→        private void advance() {
344→            next = null;
345→            while (true) {
346→                if (entryIdx < blockEntries.size()) {
347→                    next = blockEntries.get(entryIdx++);
348→                    return;
349→                }
350→                if (offset >= dataEnd)
351→                    return;
352→                // Parse next block
353→                int count = readInt(data, offset);
354→                offset += 4;
355→                blockEntries = new ArrayList<>(count);
356→                for (int i = 0; i < count; i++) {
357→                    Entry e = EntryCodec.decode(data, offset);
358→                    blockEntries.add(e);
359→                    offset += EntryCodec.encodedSize(e);
360→                }
361→                entryIdx = 0;
362→            }
363→        }
364→
365→        @Override
366→        public boolean hasNext() {
367→            return next != null;
368→        }
369→
370→        @Override
371→        public Entry next() {
372→            if (next == null)
373→                throw new NoSuchElementException();
374→            Entry result = next;
375→            advance();
376→            return result;
377→        }
378→
379→        private static int readInt(byte[] buf, int off) {
380→            return ((buf[off] & 0xFF) << 24) | ((buf[off + 1] & 0xFF) << 16)
381→                    | ((buf[off + 2] & 0xFF) << 8) | (buf[off + 3] & 0xFF);
382→        }
383→    }
384→
385→    /**
386→     * Iterates entries via key index range results, reading each entry at its absolute file offset.
387→     */
388→    private final class IndexRangeIterator implements Iterator<Entry> {
389→        private final Iterator<KeyIndex.Entry> indexIter;
390→        private Entry next;
391→
392→        IndexRangeIterator(Iterator<KeyIndex.Entry> indexIter) {
393→            this.indexIter = indexIter;
394→            advance();
395→        }
396→
397→        private void advance() {
398→            next = null;
399→            if (!indexIter.hasNext())
400→                return;
401→            KeyIndex.Entry ie = indexIter.next();
402→            try {
403→                byte[] buf = readDataAt(ie.fileOffset(), SSTableFormat.DEFAULT_BLOCK_SIZE);
404→                next = EntryCodec.decode(buf, 0);
405→            } catch (IOException e) {
406→                throw new UncheckedIOException(e);
407→            }
408→        }
409→
410→        @Override
411→        public boolean hasNext() {
412→            return next != null;
413→        }
414→
415→        @Override
416→        public Entry next() {
417→            if (next == null)
418→                throw new NoSuchElementException();
419→            Entry result = next;
420→            advance();
421→            return result;
422→        }
423→    }
424→}
