  1→package jlsm.compaction;
  2→
  3→import java.io.IOException;
  4→import java.nio.file.Path;
  5→import java.util.ArrayList;
  6→import java.util.Iterator;
  7→import java.util.List;
  8→import java.util.Objects;
  9→import java.util.Optional;
 10→import java.util.function.BiFunction;
 11→import java.util.function.LongSupplier;
 12→import jlsm.bloom.blocked.BlockedBloomFilter;
 13→import jlsm.compaction.internal.KeyRangeUtil;
 14→import jlsm.compaction.internal.MergeIterator;
 15→import jlsm.core.compaction.CompactionTask;
 16→import jlsm.core.compaction.Compactor;
 17→import jlsm.core.io.ArenaBufferPool;
 18→import jlsm.core.model.Entry;
 19→import jlsm.core.model.Level;
 20→import jlsm.core.sstable.SSTableMetadata;
 21→import jlsm.sstable.TrieSSTableReader;
 22→import jlsm.sstable.TrieSSTableWriter;
 23→
 24→/**
 25→ * SPOOKY compaction strategy (Dayan et al., VLDB 2022).
 26→ *
 27→ * <p>
 28→ * Merges one group of perfectly overlapping files at a time, using the bottom level's file
 29→ * boundaries to define groups across all levels. Achieves ~2x lower space amplification than Full
 30→ * Merge and ~2x lower write amplification than Partial Merge simultaneously.
 31→ */
 32→public final class SpookyCompactor implements Compactor, AutoCloseable {
 33→
 34→    private final LongSupplier idSupplier;
 35→    private final BiFunction<Long, Level, Path> pathFn;
 36→    private final long targetBottomFileSizeBytes;
 37→    private final ArenaBufferPool bufferPool;
 38→    private final jlsm.core.bloom.BloomFilter.Deserializer bloomDeserializer;
 39→
 40→    private SpookyCompactor(Builder builder) {
 41→        this.idSupplier = builder.idSupplier;
 42→        this.pathFn = builder.pathFn;
 43→        this.targetBottomFileSizeBytes = builder.targetBottomFileSizeBytes;
 44→        this.bloomDeserializer = builder.bloomDeserializer;
 45→        this.bufferPool = ArenaBufferPool.builder().poolSize(builder.poolSize)
 46→                .bufferSize(builder.poolBufferSizeBytes)
 47→                .acquireTimeoutMillis(builder.acquireTimeoutMillis).build();
 48→    }
 49→
 50→    // -------------------------------------------------------------------------
 51→    // selectCompaction
 52→    // -------------------------------------------------------------------------
 53→
 54→    @Override
 55→    public Optional<CompactionTask> selectCompaction(List<List<SSTableMetadata>> levelMetadata) {
 56→        Objects.requireNonNull(levelMetadata, "levelMetadata must not be null");
 57→
 58→        // Find the bottom-most non-empty level
 59→        int bottomLevelIdx = -1;
 60→        for (int i = levelMetadata.size() - 1; i >= 0; i--) {
 61→            if (!levelMetadata.get(i).isEmpty()) {
 62→                bottomLevelIdx = i;
 63→                break;
 64→            }
 65→        }
 66→
 67→        if (bottomLevelIdx < 0)
 68→            return Optional.empty();
 69→
 70→        Level bottomLevel = new Level(bottomLevelIdx);
 71→
 72→        // Bootstrap: only L0 is populated → compact all L0 files into L1
 73→        if (bottomLevelIdx == 0) {
 74→            List<SSTableMetadata> l0 = levelMetadata.get(0);
 75→            return Optional.of(new CompactionTask(new ArrayList<>(l0), Level.L0, new Level(1)));
 76→        }
 77→
 78→        // For each bottom-level file, build a candidate group and score it
 79→        List<SSTableMetadata> bottomFiles = levelMetadata.get(bottomLevelIdx);
 80→
 81→        List<SSTableMetadata> bestGroup = null;
 82→        double bestScore = Double.NEGATIVE_INFINITY;
 83→
 84→        for (SSTableMetadata bottomFile : bottomFiles) {
 85→            List<SSTableMetadata> group = new ArrayList<>();
 86→            group.add(bottomFile);
 87→            long upperSizeBytes = 0L;
 88→
 89→            // Collect overlapping files from all upper levels
 90→            for (int lvl = bottomLevelIdx - 1; lvl >= 0; lvl--) {
 91→                List<SSTableMetadata> levelFiles = levelMetadata.get(lvl);
 92→                for (SSTableMetadata upperFile : levelFiles) {
 93→                    if (KeyRangeUtil.overlaps(upperFile, bottomFile)) {
 94→                        group.add(upperFile);
 95→                        upperSizeBytes += upperFile.sizeBytes();
 96→                    }
 97→                }
 98→            }
 99→
100→            double score = (double) upperSizeBytes / Math.max(1L, bottomFile.sizeBytes());
101→
102→            if (group.size() > 1 && score > bestScore) {
103→                bestScore = score;
104→                bestGroup = group;
105→            }
106→        }
107→
108→        if (bestGroup == null)
109→            return Optional.empty();
110→
111→        // sourceLevel = lowest level index among group files
112→        int minLevelIdx = Integer.MAX_VALUE;
113→        for (SSTableMetadata m : bestGroup) {
114→            if (m.level().index() < minLevelIdx) {
115→                minLevelIdx = m.level().index();
116→            }
117→        }
118→
119→        return Optional.of(new CompactionTask(bestGroup, new Level(minLevelIdx), bottomLevel));
120→    }
121→
122→    // -------------------------------------------------------------------------
123→    // compact
124→    // -------------------------------------------------------------------------
125→
126→    @Override
127→    public List<SSTableMetadata> compact(CompactionTask task) throws IOException {
128→        Objects.requireNonNull(task, "task must not be null");
129→
130→        List<SSTableMetadata> sources = task.sourceSSTables();
131→        Level targetLevel = task.targetLevel();
132→
133→        // Determine if this is a bottom-level compaction (tombstones can be dropped)
134→        int maxSourceLevelIdx = 0;
135→        for (SSTableMetadata m : sources) {
136→            if (m.level().index() > maxSourceLevelIdx) {
137→                maxSourceLevelIdx = m.level().index();
138→            }
139→        }
140→        boolean isBottomLevel = (targetLevel.index() == maxSourceLevelIdx);
141→
142→        // Open all source SSTables (eager: one big read per file)
143→        List<TrieSSTableReader> readers = new ArrayList<>(sources.size());
144→        try {
145→            for (SSTableMetadata meta : sources) {
146→                readers.add(TrieSSTableReader.open(meta.path(), bloomDeserializer));
147→            }
148→
149→            // Build merge iterator
150→            List<Iterator<Entry>> iters = new ArrayList<>(readers.size());
151→            for (TrieSSTableReader reader : readers) {
152→                iters.add(reader.scan());
153→            }
154→            MergeIterator merge = new MergeIterator(iters);
155→
156→            return writeMergedOutput(merge, targetLevel, isBottomLevel);
157→
158→        } finally {
159→            for (TrieSSTableReader r : readers) {
160→                try {
161→                    r.close();
162→                } catch (IOException ignored) {
163→                }
164→            }
165→        }
166→    }
167→
168→    private List<SSTableMetadata> writeMergedOutput(MergeIterator merge, Level targetLevel,
169→            boolean isBottomLevel) throws IOException {
170→        List<SSTableMetadata> output = new ArrayList<>();
171→        TrieSSTableWriter writer = null;
172→        java.lang.foreign.MemorySegment scratchBuf = null;
173→
174→        try {
175→            scratchBuf = bufferPool.acquire();
176→
177→            Entry prev = null;
178→
179→            while (merge.hasNext()) {
180→                Entry entry = merge.next();
181→
182→                // Dedup: skip lower-seqnum versions of the same key
183→                if (prev != null && KeyRangeUtil.keysEqual(entry.key(), prev.key())) {
184→                    continue;
185→                }
186→
187→                // Drop tombstones at the bottom level
188→                if (isBottomLevel && entry instanceof Entry.Delete) {
189→                    prev = entry;
190→                    continue;
191→                }
192→
193→                // Open a new writer if needed
194→                if (writer == null) {
195→                    long id = idSupplier.getAsLong();
196→                    Path outputPath = pathFn.apply(id, targetLevel);
197→                    writer = new TrieSSTableWriter(id, targetLevel, outputPath);
198→                }
199→
200→                writer.append(entry);
201→                prev = entry;
202→
203→                // Split output file if it has reached the target size
204→                if (writer.approximateSizeBytes() >= targetBottomFileSizeBytes) {
205→                    output.add(writer.finish());
206→                    writer.close();
207→                    writer = null;
208→                }
209→            }
210→
211→            // Finish any remaining in-progress writer
212→            if (writer != null && writer.entryCount() > 0) {
213→                output.add(writer.finish());
214→                writer.close();
215→                writer = null;
216→            }
217→
218→        } catch (IOException | RuntimeException e) {
219→            if (writer != null) {
220→                try {
221→                    writer.close();
222→                } catch (IOException ignored) {
223→                }
224→                writer = null;
225→            }
226→            throw (e instanceof IOException ioe) ? ioe : new IOException("merge failed", e);
227→        } finally {
228→            if (scratchBuf != null) {
229→                bufferPool.release(scratchBuf);
230→            }
231→        }
232→
233→        return output;
234→    }
235→
236→    @Override
237→    public void close() {
238→        bufferPool.close();
239→    }
240→
241→    // -------------------------------------------------------------------------
242→    // Builder
243→    // -------------------------------------------------------------------------
244→
245→    public static Builder builder() {
246→        return new Builder();
247→    }
248→
249→    public static final class Builder {
250→        private LongSupplier idSupplier;
251→        private BiFunction<Long, Level, Path> pathFn;
252→        private long targetBottomFileSizeBytes = 64L * 1024 * 1024;
253→        private int poolSize = 4;
254→        private long poolBufferSizeBytes = 1024 * 1024L;
255→        private long acquireTimeoutMillis = 30_000L;
256→        private jlsm.core.bloom.BloomFilter.Deserializer bloomDeserializer = BlockedBloomFilter
257→                .deserializer();
258→
259→        public Builder idSupplier(LongSupplier idSupplier) {
260→            Objects.requireNonNull(idSupplier, "idSupplier must not be null");
261→            this.idSupplier = idSupplier;
262→            return this;
263→        }
264→
265→        public Builder pathFn(BiFunction<Long, Level, Path> pathFn) {
266→            Objects.requireNonNull(pathFn, "pathFn must not be null");
267→            this.pathFn = pathFn;
268→            return this;
269→        }
270→
271→        public Builder targetBottomFileSizeBytes(long bytes) {
272→            if (bytes < 1)
273→                throw new IllegalArgumentException("targetBottomFileSizeBytes must be >= 1");
274→            this.targetBottomFileSizeBytes = bytes;
275→            return this;
276→        }
277→
278→        public Builder poolSize(int poolSize) {
279→            if (poolSize < 1)
280→                throw new IllegalArgumentException("poolSize must be >= 1");
281→            this.poolSize = poolSize;
282→            return this;
283→        }
284→
285→        public Builder poolBufferSizeBytes(long bytes) {
286→            if (bytes < 1)
287→                throw new IllegalArgumentException("poolBufferSizeBytes must be >= 1");
288→            this.poolBufferSizeBytes = bytes;
289→            return this;
290→        }
291→
292→        public Builder acquireTimeoutMillis(long millis) {
293→            if (millis <= 0)
294→                throw new IllegalArgumentException("acquireTimeoutMillis must be > 0");
295→            this.acquireTimeoutMillis = millis;
296→            return this;
297→        }
298→
299→        /**
300→         * Overrides the {@link jlsm.core.bloom.BloomFilter.Deserializer} used to open source
301→         * SSTables during compaction. Defaults to {@code BlockedBloomFilter.deserializer()}. Must
302→         * match the deserializer used when those SSTables were originally written.
303→         */
304→        public Builder bloomDeserializer(jlsm.core.bloom.BloomFilter.Deserializer deserializer) {
305→            this.bloomDeserializer = Objects.requireNonNull(deserializer,
306→                    "bloomDeserializer must not be null");
307→            return this;
308→        }
309→
310→        public SpookyCompactor build() {
311→            if (idSupplier == null)
312→                throw new IllegalStateException("idSupplier must be configured");
313→            if (pathFn == null)
314→                throw new IllegalStateException("pathFn must be configured");
315→            return new SpookyCompactor(this);
316→        }
317→    }
318→}
