 1→package jlsm.compaction.internal;
 2→
 3→import java.util.Comparator;
 4→import java.util.Iterator;
 5→import java.util.List;
 6→import java.util.NoSuchElementException;
 7→import java.util.Objects;
 8→import java.util.PriorityQueue;
 9→import jlsm.core.model.Entry;
10→
11→/**
12→ * N-way merge iterator over sorted {@link Entry} streams.
13→ *
14→ * <p>
15→ * Heap ordering: key ASC (unsigned lexicographic), seqNum DESC for equal keys. This means the entry
16→ * with the highest sequence number for any given key surfaces first.
17→ */
18→public final class MergeIterator implements Iterator<Entry> {
19→
20→    private record HeapEntry(Entry entry, Iterator<Entry> source) {
21→    }
22→
23→    private static final Comparator<HeapEntry> HEAP_ORDER = (x, y) -> {
24→        int keyCmp = KeyRangeUtil.compareUnsigned(x.entry().key(), y.entry().key());
25→        if (keyCmp != 0)
26→            return keyCmp;
27→        // Same key: higher seqNum comes first (DESC)
28→        return Long.compare(y.entry().sequenceNumber().value(), x.entry().sequenceNumber().value());
29→    };
30→
31→    private final PriorityQueue<HeapEntry> heap;
32→
33→    public MergeIterator(List<Iterator<Entry>> sources) {
34→        Objects.requireNonNull(sources, "sources must not be null");
35→
36→        this.heap = new PriorityQueue<>(Math.max(1, sources.size()), HEAP_ORDER);
37→        for (Iterator<Entry> src : sources) {
38→            if (src.hasNext()) {
39→                heap.offer(new HeapEntry(src.next(), src));
40→            }
41→        }
42→    }
43→
44→    @Override
45→    public boolean hasNext() {
46→        return !heap.isEmpty();
47→    }
48→
49→    @Override
50→    public Entry next() {
51→        if (heap.isEmpty())
52→            throw new NoSuchElementException();
53→        HeapEntry min = heap.poll();
54→        // Advance the source iterator that yielded this entry
55→        if (min.source().hasNext()) {
56→            heap.offer(new HeapEntry(min.source().next(), min.source()));
57→        }
58→        return min.entry();
59→    }
60→}
