 31→/**
 32→ * WAL implementation for local filesystems using memory-mapped I/O.
 33→ *
 34→ * <p>
 35→ * Each segment file is pre-allocated to {@code segmentSize} bytes and mapped READ_WRITE. Records
 36→ * are appended at {@code writePosition} and forced to disk after every write. When a segment is
 37→ * full the file is truncated to the valid write position and a new segment is created.
 38→ */
 39→public final class LocalWriteAheadLog implements WriteAheadLog {
 40→
 41→    private static final long DEFAULT_SEGMENT_SIZE = 64L * 1024 * 1024; // 64 MiB
 42→    private static final int DEFAULT_POOL_SIZE = 4;
 43→    private static final long DEFAULT_BUFFER_SIZE = 1024 * 1024L; // 1 MiB
 44→    private static final long DEFAULT_ACQUIRE_TIMEOUT_MILLIS = 5_000L;
 45→
 46→    private final Path directory;
 47→    private final long segmentSize;
 48→    private final ArenaBufferPool bufferPool;
 49→
 50→    // Write path — serialized by writeLock
 51→    private final ReentrantLock writeLock = new ReentrantLock();
 52→    private final AtomicLong nextSequence = new AtomicLong(1L);
 53→    private long activeSegmentNumber;
 54→    private MappedByteBuffer mappedBuffer;
 55→    private FileChannel activeChannel;
 56→    private int writePosition;
 57→
 58→    // segmentNumber → first sequence value in that segment
 59→    private final NavigableMap<Long, Long> segmentIndex = new ConcurrentSkipListMap<>();
 60→    private final ReentrantReadWriteLock indexLock = new ReentrantReadWriteLock();
 61→
 62→    private LocalWriteAheadLog(Path directory, long segmentSize, ArenaBufferPool bufferPool)
 63→            throws IOException {
 64→        assert directory != null : "directory must not be null";
 65→        assert segmentSize > 0 : "segmentSize must be positive";
 66→        assert bufferPool != null : "bufferPool must not be null";
 67→
 68→        this.directory = directory;
 69→        this.segmentSize = segmentSize;
 70→        this.bufferPool = bufferPool;
 71→
 72→        recover();
 73→    }
 74→
 75→    // -------------------------------------------------------------------------
 76→    // Recovery
 77→    // -------------------------------------------------------------------------
 78→
 79→    private void recover() throws IOException {
 80→        List<Path> segments = SegmentFile.listSorted(directory);
 81→
 82→        if (segments.isEmpty()) {
 83→            // Brand new WAL — create segment 1
 84→            activeSegmentNumber = 1L;
 85→            nextSequence.set(1L);
 86→            openNewSegment(activeSegmentNumber);
 87→            return;
 88→        }
 89→
 90→        // Scan each segment for valid records; build segmentIndex
 91→        long lastValidSeq = 0L;
 92→
 93→        for (Path segPath : segments) {
 94→            long segNum = SegmentFile.parseNumber(segPath.getFileName().toString());
 95→            assert segNum >= 0 : "invalid segment file in recovery: " + segPath;
 96→
 97→            long[] scanResult = scanSegment(segPath);
 98→            long firstSeq = scanResult[0]; // -1 if empty
 99→            long lastSeq = scanResult[1]; // -1 if empty
100→            int validBytes = (int) scanResult[2];
101→
102→            if (firstSeq >= 0) {
103→                segmentIndex.put(segNum, firstSeq);
104→                if (lastSeq > lastValidSeq)
105→                    lastValidSeq = lastSeq;
106→            }
107→
108→            boolean isLast = segPath.equals(segments.get(segments.size() - 1));
109→            if (isLast) {
110→                activeSegmentNumber = segNum;
111→                // Open the last segment for writing; ensure it is at segmentSize
112→                ensureSegmentSize(segPath);
113→                activeChannel = FileChannel.open(segPath, StandardOpenOption.READ,
114→                        StandardOpenOption.WRITE);
115→                mappedBuffer = activeChannel.map(FileChannel.MapMode.READ_WRITE, 0, segmentSize);
116→                writePosition = validBytes;
117→            }
118→        }
119→
120→        nextSequence.set(lastValidSeq + 1L);
121→    }
122→
123→    /**
124→     * Scans a segment file and returns {firstSeq, lastSeq, validByteCount}. firstSeq/lastSeq = -1
125→     * if no valid records found.
126→     */
127→    private long[] scanSegment(Path segPath) throws IOException {
128→        long fileSize = Files.size(segPath);
129→        if (fileSize == 0)
130→            return new long[]{ -1, -1, 0 };
131→
132→        long mapSize = Math.min(fileSize, segmentSize);
133→        long firstSeq = -1L;
134→        long lastSeq = -1L;
135→        int validBytes = 0;
136→
137→        try (FileChannel fc = FileChannel.open(segPath, StandardOpenOption.READ)) {
138→            MappedByteBuffer mbb = fc.map(FileChannel.MapMode.READ_ONLY, 0, mapSize);
139→            MemorySegment seg = MemorySegment.ofBuffer(mbb);
140→            long pos = 0;
141→            while (pos < mapSize) {
142→                Entry entry;
143→                try {
144→                    entry = WalRecord.decode(seg, pos, mapSize - pos);
145→                } catch (IOException e) {
146→                    // CRC mismatch on partially-written record — stop here
147→                    break;
148→                }
149→                if (entry == null)
150→                    break;
151→
152→                long seqVal = entry.sequenceNumber().value();
153→                if (firstSeq < 0)
154→                    firstSeq = seqVal;
155→                if (seqVal > lastSeq)
156→                    lastSeq = seqVal;
157→
158→                // Advance by frame size: 4 (frame length field) + frameContentLen
159→                int frameContentLen = readFrameContentLen(seg, pos);
160→                pos += 4 + frameContentLen;
161→                validBytes = (int) pos;
162→            }
163→        }
164→
165→        return new long[]{ firstSeq, lastSeq, validBytes };
166→    }
167→
168→    private static final ValueLayout.OfInt INT_BE_UNALIGNED = ValueLayout.JAVA_INT
169→            .withOrder(java.nio.ByteOrder.BIG_ENDIAN).withByteAlignment(1);
170→
171→    private int readFrameContentLen(MemorySegment seg, long pos) {
172→        return seg.get(INT_BE_UNALIGNED, pos);
173→    }
174→
175→    private void ensureSegmentSize(Path path) throws IOException {
176→        long size = Files.size(path);
177→        if (size < segmentSize) {
178→            try (FileChannel fc = FileChannel.open(path, StandardOpenOption.WRITE)) {
179→                fc.write(ByteBuffer.allocate(1), segmentSize - 1);
180→            }
181→        }
182→    }
183→
184→    private void openNewSegment(long segNum) throws IOException {
185→        Path path = directory.resolve(SegmentFile.toFileName(segNum));
186→        // Pre-allocate
187→        try (FileChannel fc = FileChannel.open(path, StandardOpenOption.CREATE_NEW,
188→                StandardOpenOption.WRITE)) {
189→            fc.write(ByteBuffer.allocate(1), segmentSize - 1);
190→        }
191→        activeChannel = FileChannel.open(path, StandardOpenOption.READ, StandardOpenOption.WRITE);
192→        mappedBuffer = activeChannel.map(FileChannel.MapMode.READ_WRITE, 0, segmentSize);
193→        writePosition = 0;
194→    }
195→
196→    // -------------------------------------------------------------------------
197→    // WriteAheadLog interface
198→    // -------------------------------------------------------------------------
199→
200→    @Override
201→    public SequenceNumber append(Entry entry) throws IOException {
202→        Objects.requireNonNull(entry, "entry must not be null");
203→
204→        writeLock.lock();
205→        try {
206→            long seq = nextSequence.getAndIncrement();
207→            // Re-wrap the entry with the assigned sequence number
208→            Entry stamped = stamp(entry, new SequenceNumber(seq));
209→
210→            MemorySegment buf = bufferPool.acquire();
211→            try {
212→                int n = WalRecord.encode(stamped, buf);
213→
214→                if (n > segmentSize - writePosition) {
215→                    rollSegment(seq);
216→                }
217→
218→                MemorySegment mapped = MemorySegment.ofBuffer(mappedBuffer);
219→                MemorySegment.copy(buf, 0, mapped, writePosition, n);
220→                writePosition += n;
221→                mappedBuffer.force(writePosition - n, n);
222→            } finally {
223→                bufferPool.release(buf);
224→            }
225→
226→            return new SequenceNumber(seq);
227→        } finally {
228→            writeLock.unlock();
229→        }
230→    }
231→
232→    private void rollSegment(long firstSeqInNewSegment) throws IOException {
233→        assert writeLock.isHeldByCurrentThread() : "writeLock must be held during rollover";
234→
235→        // Flush and close current segment
236→        mappedBuffer.force();
237→        activeChannel.truncate(writePosition);
238→        activeChannel.close();
239→        mappedBuffer = null;
240→        activeChannel = null;
241→
242→        // Create next segment
243→        activeSegmentNumber++;
244→        openNewSegment(activeSegmentNumber);
245→
246→        // Update segment index
247→        indexLock.writeLock().lock();
248→        try {
249→            segmentIndex.put(activeSegmentNumber, firstSeqInNewSegment);
250→        } finally {
251→            indexLock.writeLock().unlock();
252→        }
253→    }
254→
255→    private static Entry stamp(Entry entry, SequenceNumber seq) {
256→        return switch (entry) {
257→            case Entry.Put put -> new Entry.Put(put.key(), put.value(), seq);
258→            case Entry.Delete del -> new Entry.Delete(del.key(), seq);
259→        };
260→    }
261→
262→    @Override
263→    public Iterator<Entry> replay(SequenceNumber from) throws IOException {
264→        Objects.requireNonNull(from, "from must not be null");
265→
266→        List<Path> allSegments = SegmentFile.listSorted(directory);
267→        if (allSegments.isEmpty())
268→            return Collections.emptyIterator();
269→
270→        // Find the first segment to include: last segment whose firstSeq <= from,
271→        // or the very first segment if all firstSeqs > from.
272→        List<Path> toScan = segmentsForReplay(allSegments, from);
273→        return new ReplayIterator(toScan, from, segmentSize);
274→    }
275→
276→    private List<Path> segmentsForReplay(List<Path> allSegments, SequenceNumber from) {
277→        indexLock.readLock().lock();
278→        try {
279→            if (segmentIndex.isEmpty())
280→                return new ArrayList<>(allSegments);
281→
282→            // Find the start: last segment number with firstSeq <= from.value()
283→            // Since segmentIndex maps segNum -> firstSeq, iterate to find the floor by value.
284→            long startSegNum = -1L;
285→            for (var entry : segmentIndex.entrySet()) {
286→                if (entry.getValue() <= from.value()) {
287→                    startSegNum = entry.getKey();
288→                }
289→            }
290→
291→            final long finalStart = startSegNum;
292→            if (finalStart < 0) {
293→                // All segments have firstSeq > from — include all
294→                return new ArrayList<>(allSegments);
295→            }
296→
297→            List<Path> result = new ArrayList<>();
298→            for (Path p : allSegments) {
299→                long segNum = SegmentFile.parseNumber(p.getFileName().toString());
300→                if (segNum >= finalStart)
301→                    result.add(p);
302→            }
303→            return result;
304→        } finally {
305→            indexLock.readLock().unlock();
306→        }
307→    }
308→
309→    @Override
310→    public void truncateBefore(SequenceNumber upTo) throws IOException {
311→        Objects.requireNonNull(upTo, "upTo must not be null");
312→
313→        List<Path> allSegments = SegmentFile.listSorted(directory);
314→
315→        indexLock.writeLock().lock();
316→        try {
317→            // A segment is fully obsolete when the NEXT segment's firstSeq <= upTo.value(),
318→            // meaning every record in this segment is strictly < upTo.
319→            for (int i = 0; i < allSegments.size() - 1; i++) {
320→                Path current = allSegments.get(i);
321→                Path next = allSegments.get(i + 1);
322→                long nextSegNum = SegmentFile.parseNumber(next.getFileName().toString());
323→                Long nextFirstSeq = segmentIndex.get(nextSegNum);
324→
325→                if (nextFirstSeq != null && nextFirstSeq <= upTo.value()) {
326→                    long curSegNum = SegmentFile.parseNumber(current.getFileName().toString());
327→                    Files.deleteIfExists(current);
328→                    segmentIndex.remove(curSegNum);
329→                }
330→            }
331→        } finally {
332→            indexLock.writeLock().unlock();
333→        }
334→    }
335→
336→    @Override
337→    public SequenceNumber lastSequenceNumber() throws IOException {
338→        long next = nextSequence.get();
339→        if (next <= 1L)
340→            return SequenceNumber.ZERO;
341→        return new SequenceNumber(next - 1L);
342→    }
343→
344→    @Override
345→    public void close() throws IOException {
346→        writeLock.lock();
347→        IOException deferred = null;
348→        try {
349→            if (mappedBuffer != null) {
350→                try {
351→                    mappedBuffer.force();
352→                } catch (UncheckedIOException e) {
353→                    deferred = e.getCause() != null ? e.getCause() : new IOException(e);
354→                }
355→                mappedBuffer = null;
356→            }
357→            if (activeChannel != null) {
358→                try {
359→                    activeChannel.close();
360→                } catch (IOException e) {
361→                    if (deferred != null) {
362→                        deferred.addSuppressed(e);
363→                    } else {
364→                        deferred = e;
365→                    }
366→                }
367→                activeChannel = null;
368→            }
369→        } finally {
370→            writeLock.unlock();
371→        }
372→        bufferPool.close();
373→        if (deferred != null)
374→            throw deferred;
375→    }
376→
377→    // -------------------------------------------------------------------------
378→    // Replay iterator
379→    // -------------------------------------------------------------------------
380→
381→    private static final class ReplayIterator implements Iterator<Entry> {
382→
383→        private final List<Path> segments;
384→        private final SequenceNumber from;
385→        private final long segmentSize;
386→        private int segIdx = 0;
387→        private Entry next;
388→        // Per-segment state
389→        private MemorySegment currentSeg;
390→        private long segAvailable;
391→        private long segPos;
392→
393→        ReplayIterator(List<Path> segments, SequenceNumber from, long segmentSize) {
394→            this.segments = segments;
395→            this.from = from;
396→            this.segmentSize = segmentSize;
397→            advance();
398→        }
399→
400→        private void advance() {
401→            next = null;
402→            while (next == null) {
403→                if (currentSeg == null) {
404→                    if (segIdx >= segments.size())
405→                        return;
406→                    loadSegment(segments.get(segIdx++));
407→                    if (currentSeg == null)
408→                        continue;
409→                }
410→                Entry candidate = readNext();
411→                if (candidate == null) {
412→                    currentSeg = null;
413→                    continue;
414→                }
415→                if (candidate.sequenceNumber().compareTo(from) >= 0) {
416→                    next = candidate;
417→                }
418→                // else skip and keep scanning
419→            }
420→        }
421→
422→        private void loadSegment(Path path) {
423→            try {
424→                long fileSize = Files.size(path);
425→                if (fileSize == 0)
426→                    return;
427→                long mapSize = Math.min(fileSize, segmentSize);
428→                FileChannel fc = FileChannel.open(path, StandardOpenOption.READ);
429→                MappedByteBuffer mbb = fc.map(FileChannel.MapMode.READ_ONLY, 0, mapSize);
430→                fc.close();
431→                currentSeg = MemorySegment.ofBuffer(mbb);
432→                segAvailable = mapSize;
433→                segPos = 0;
434→            } catch (IOException e) {
435→                throw new UncheckedIOException(e);
436→            }
437→        }
438→
439→        private Entry readNext() {
440→            while (segPos < segAvailable) {
441→                Entry entry;
442→                try {
443→                    entry = WalRecord.decode(currentSeg, segPos, segAvailable - segPos);
444→                } catch (IOException e) {
445→                    // CRC mismatch — treat as end of valid data in this segment
446→                    return null;
447→                }
448→                if (entry == null)
449→                    return null;
450→
451→                int frameContentLen = currentSeg.get(INT_BE_UNALIGNED, segPos);
452→                segPos += 4L + frameContentLen;
453→                return entry;
454→            }
455→            return null;
456→        }
457→
458→        @Override
459→        public boolean hasNext() {
460→            return next != null;
461→        }
462→
463→        @Override
464→        public Entry next() {
465→            if (next == null)
466→                throw new NoSuchElementException();
467→            Entry result = next;
468→            advance();
469→            return result;
470→        }
471→    }
