  1→package jlsm.bloom.blocked;
  2→
  3→import java.lang.foreign.Arena;
  4→import java.lang.foreign.MemorySegment;
  5→import java.lang.foreign.ValueLayout;
  6→import java.nio.ByteOrder;
  7→import java.util.Objects;
  8→import jlsm.bloom.hash.Murmur3Hash;
  9→import jlsm.core.bloom.BloomFilter;
 10→
 11→/**
 12→ * A cache-friendly bloom filter that partitions its bit array into 512-bit (one cache-line) blocks.
 13→ * All {@code k} hash probes for a given key are confined to a single block, improving cache
 14→ * locality compared to a standard bloom filter that may probe across many cache lines.
 15→ *
 16→ * <p>
 17→ * <b>Pipeline position:</b> constructed during SSTable flush (one filter per SSTable), then
 18→ * serialized into the SSTable footer. On the read path, the filter is deserialized and consulted
 19→ * before performing random I/O.
 20→ *
 21→ * <p>
 22→ * <b>Algorithm:</b> uses MurmurHash3 x64-128 to derive two 64-bit seeds {@code (h1, h2)}, then
 23→ * applies double hashing: {@code bitPos = (h1 + i * h2) & 511} for {@code i} in {@code [0, k)}. All
 24→ * probes for a single key land within the same 512-bit block, selected by
 25→ * {@code blockIndex = (h1 & Long.MAX_VALUE) % numBlocks}.
 26→ *
 27→ * <p>
 28→ * <b>Why {@code h2} must be forced odd:</b> the bit positions form an arithmetic sequence
 29→ * {@code h1, h1+h2, h1+2·h2, …} modulo 512. When {@code h2} is even, the sequence has period
 30→ * {@code 512 / gcd(h2, 512) < 512}, so the {@code k} probes collapse onto a small subset of bit
 31→ * positions rather than spreading across the full block. Empirically this raises the false-positive
 32→ * rate roughly 6× above the target (e.g., ~7% instead of ~1%). Forcing {@code h2 |= 1} makes it
 33→ * coprime to 512, guaranteeing period 512 and keeping the empirical FPR within the expected range.
 34→ * <strong>Do not remove the {@code | 1L} in {@link #add} and {@link #mightContain}.</strong>
 35→ *
 36→ * <p>
 37→ * <b>Serialization format (big-endian):</b>
 38→ *
 39→ * <pre>
 40→ *   [int  numBlocks       ]  4 bytes
 41→ *   [int  numHashFunctions]  4 bytes
 42→ *   [long insertionCount  ]  8 bytes
 43→ *   [long[] bits          ]  numBlocks * 64 bytes (8 longs per block)
 44→ * </pre>
 45→ *
 46→ * Total: {@code 16 + numBlocks * 64} bytes.
 47→ *
 48→ * <p>
 49→ * <b>Thread-safety:</b> not thread-safe during the construction ({@link #add}) phase. Once
 50→ * serialized and deserialized for reads, {@link #mightContain} is safe for concurrent use because
 51→ * the bit array is read-only after deserialization.
 52→ */
 53→public final class BlockedBloomFilter implements BloomFilter {
 54→
 55→    private static final double LN2 = Math.log(2.0);
 56→    private static final double LN2_SQUARED = LN2 * LN2;
 57→
 58→    /** Number of longs per 512-bit block. */
 59→    private static final int LONGS_PER_BLOCK = 8;
 60→
 61→    private final long[] bits;
 62→    private final int numBlocks;
 63→    private final int numHashFunctions;
 64→    private long insertionCount;
 65→
 66→    /**
 67→     * Constructs a new, empty {@code BlockedBloomFilter} sized for {@code expectedInsertions} keys
 68→     * at the given {@code targetFpr} false-positive rate.
 69→     *
 70→     * @param expectedInsertions the anticipated number of distinct keys to be added; must be
 71→     *            positive
 72→     * @param targetFpr the desired false-positive probability in {@code (0.0, 1.0)}
 73→     * @throws IllegalArgumentException if {@code expectedInsertions <= 0} or {@code targetFpr} is
 74→     *             not in {@code (0.0, 1.0)}
 75→     */
 76→    public BlockedBloomFilter(int expectedInsertions, double targetFpr) {
 77→        if (expectedInsertions <= 0) {
 78→            throw new IllegalArgumentException(
 79→                    "expectedInsertions must be positive, got: " + expectedInsertions);
 80→        }
 81→        if (targetFpr <= 0.0 || targetFpr >= 1.0) {
 82→            throw new IllegalArgumentException(
 83→                    "targetFpr must be in (0.0, 1.0), got: " + targetFpr);
 84→        }
 85→
 86→        // m/n = -ln(fpr) / ln2^2
 87→        double bitsPerElement = -Math.log(targetFpr) / LN2_SQUARED;
 88→        long totalBits = Math.max(512L, (long) Math.ceil(bitsPerElement * expectedInsertions));
 89→
 90→        this.numBlocks = (int) Math.max(1L, (totalBits + 511) / 512);
 91→        this.bits = new long[numBlocks * LONGS_PER_BLOCK];
 92→
 93→        // k = (m/n) * ln2
 94→        int k = (int) Math.round(bitsPerElement * LN2);
 95→        this.numHashFunctions = Math.max(1, Math.min(30, k));
 96→        this.insertionCount = 0;
 97→    }
 98→
 99→    /** Private constructor used during deserialization. */
100→    private BlockedBloomFilter(int numBlocks, int numHashFunctions, long insertionCount,
101→            long[] bits) {
102→        assert numBlocks > 0 : "numBlocks must be positive";
103→        assert numHashFunctions >= 1 && numHashFunctions <= 30
104→                : "numHashFunctions must be in [1,30]";
105→        assert insertionCount >= 0 : "insertionCount must be non-negative";
106→        assert bits != null && bits.length == numBlocks * LONGS_PER_BLOCK
107→                : "bits array size mismatch";
108→        this.numBlocks = numBlocks;
109→        this.numHashFunctions = numHashFunctions;
110→        this.insertionCount = insertionCount;
111→        this.bits = bits;
112→    }
113→
114→    /** {@inheritDoc} */
115→    @Override
116→    public void add(MemorySegment key) {
117→        Objects.requireNonNull(key, "key must not be null");
118→        long[] hashes = Murmur3Hash.hash128(key);
119→        assert hashes.length == 2 : "hash128 must return exactly 2 longs";
120→        long h1 = hashes[0];
121→        // Force h2 odd so it is coprime to the 512-bit block size, ensuring the double-hashing
122→        // sequence (h1 + i*h2) mod 512 visits all 512 positions before repeating.
123→        long h2 = hashes[1] | 1L;
124→
125→        int blockIndex = (int) ((h1 & Long.MAX_VALUE) % numBlocks);
126→        assert blockIndex >= 0 && blockIndex < numBlocks : "blockIndex out of range";
127→        int blockBase = blockIndex * LONGS_PER_BLOCK;
128→
129→        for (int i = 0; i < numHashFunctions; i++) {
130→            int bitPos = (int) ((h1 + (long) i * h2) & 511);
131→            assert bitPos >= 0 && bitPos < 512 : "bitPos out of [0,512)";
132→            bits[blockBase + (bitPos >>> 6)] |= (1L << (bitPos & 63));
133→        }
134→        insertionCount++;
135→    }
136→
137→    /** {@inheritDoc} */
138→    @Override
139→    public boolean mightContain(MemorySegment key) {
140→        Objects.requireNonNull(key, "key must not be null");
141→        long[] hashes = Murmur3Hash.hash128(key);
142→        assert hashes.length == 2 : "hash128 must return exactly 2 longs";
143→        long h1 = hashes[0];
144→        // Must match the | 1L in add(); see class-level Javadoc for why h2 must be odd.
145→        long h2 = hashes[1] | 1L;
146→
147→        int blockIndex = (int) ((h1 & Long.MAX_VALUE) % numBlocks);
148→        assert blockIndex >= 0 && blockIndex < numBlocks : "blockIndex out of range";
149→        int blockBase = blockIndex * LONGS_PER_BLOCK;
150→
151→        for (int i = 0; i < numHashFunctions; i++) {
152→            int bitPos = (int) ((h1 + (long) i * h2) & 511);
153→            assert bitPos >= 0 && bitPos < 512 : "bitPos out of [0,512)";
154→            if ((bits[blockBase + (bitPos >>> 6)] & (1L << (bitPos & 63))) == 0) {
155→                return false;
156→            }
157→        }
158→        return true;
159→    }
160→
161→    /**
162→     * {@inheritDoc}
163→     *
164→     * <p>
165→     * Computes the theoretical false-positive rate given the number of insertions so far:
166→     * {@code (1 - e^(-k * n / m))^k} where {@code m} is the total bit count, {@code n} is
167→     * {@link #insertionCount}, and {@code k} is the number of hash functions.
168→     */
169→    @Override
170→    public double falsePositiveRate() {
171→        long m = (long) numBlocks * LONGS_PER_BLOCK * 64L;
172→        if (insertionCount == 0 || m == 0) {
173→            return 0.0;
174→        }
175→        double exponent = -(double) numHashFunctions * insertionCount / m;
176→        double prob = Math.pow(1.0 - Math.exp(exponent), numHashFunctions);
177→        return Math.max(0.0, Math.min(1.0, prob));
178→    }
179→
180→    /**
181→     * {@inheritDoc}
182→     *
183→     * <p>
184→     * Serialized layout (big-endian):
185→     *
186→     * <pre>
187→     *   [int  numBlocks       ]  4 bytes
188→     *   [int  numHashFunctions]  4 bytes
189→     *   [long insertionCount  ]  8 bytes
190→     *   [long[] bits          ]  numBlocks * 64 bytes
191→     * </pre>
192→     */
193→    @Override
194→    public MemorySegment serialize() {
195→        assert numBlocks > 0 : "numBlocks must be positive";
196→        assert bits.length == numBlocks * LONGS_PER_BLOCK : "bits array size mismatch";
197→        long byteSize = 16L + (long) numBlocks * LONGS_PER_BLOCK * Long.BYTES;
198→        MemorySegment seg = Arena.ofAuto().allocate(byteSize);
199→        seg.set(ValueLayout.JAVA_INT.withOrder(ByteOrder.BIG_ENDIAN), 0, numBlocks);
200→        seg.set(ValueLayout.JAVA_INT.withOrder(ByteOrder.BIG_ENDIAN), 4, numHashFunctions);
201→        seg.set(ValueLayout.JAVA_LONG.withOrder(ByteOrder.BIG_ENDIAN), 8, insertionCount);
202→        for (int i = 0; i < bits.length; i++) {
203→            seg.set(ValueLayout.JAVA_LONG.withOrder(ByteOrder.BIG_ENDIAN), 16L + i * 8L, bits[i]);
204→        }
205→        return seg;
206→    }
207→
208→    /**
209→     * Returns a {@link BloomFilter.Deserializer} that reconstructs a {@code BlockedBloomFilter}
210→     * from bytes produced by {@link #serialize}.
211→     *
212→     * @return a deserializer for this filter type; never null
213→     */
214→    public static BloomFilter.Deserializer deserializer() {
215→        return bytes -> {
216→            Objects.requireNonNull(bytes, "bytes must not be null");
217→            if (bytes.byteSize() < 16) {
218→                throw new IllegalArgumentException(
219→                        "serialized bloom filter must be at least 16 bytes, got: "
220→                                + bytes.byteSize());
221→            }
222→            int numBlocks = bytes.get(ValueLayout.JAVA_INT.withOrder(ByteOrder.BIG_ENDIAN), 0);
223→            int numHashFunctions = bytes.get(ValueLayout.JAVA_INT.withOrder(ByteOrder.BIG_ENDIAN),
224→                    4);
225→            if (numBlocks <= 0) {
226→                throw new IllegalArgumentException("numBlocks must be positive, got: " + numBlocks);
227→            }
228→            if (numHashFunctions < 1 || numHashFunctions > 30) {
229→                throw new IllegalArgumentException(
230→                        "numHashFunctions must be in [1,30], got: " + numHashFunctions);
231→            }
232→            long expectedSize = 16L + (long) numBlocks * LONGS_PER_BLOCK * Long.BYTES;
233→            if (bytes.byteSize() != expectedSize) {
234→                throw new IllegalArgumentException(
235→                        "serialized size %d does not match expected %d for numBlocks=%d"
236→                                .formatted(bytes.byteSize(), expectedSize, numBlocks));
237→            }
238→            long insertionCount = bytes.get(ValueLayout.JAVA_LONG.withOrder(ByteOrder.BIG_ENDIAN),
239→                    8);
240→            long[] bits = new long[numBlocks * LONGS_PER_BLOCK];
241→            for (int i = 0; i < bits.length; i++) {
242→                bits[i] = bytes.get(ValueLayout.JAVA_LONG.withOrder(ByteOrder.BIG_ENDIAN),
243→                        16L + i * 8L);
244→            }
245→            return new BlockedBloomFilter(numBlocks, numHashFunctions, insertionCount, bits);
246→        };
247→    }
248→}
