  1→package jlsm.sstable.internal;
  2→
  3→import java.lang.foreign.MemorySegment;
  4→import java.lang.foreign.ValueLayout;
  5→import java.util.ArrayDeque;
  6→import java.util.ArrayList;
  7→import java.util.Arrays;
  8→import java.util.Deque;
  9→import java.util.Iterator;
 10→import java.util.List;
 11→import java.util.Objects;
 12→import java.util.Optional;
 13→
 14→/**
 15→ * An in-memory trie (prefix tree) mapping keys to absolute file offsets. Built from a sorted flat
 16→ * list of (key, offset) pairs and provides O(|key|) point lookup and in-order iteration.
 17→ *
 18→ * <p>
 19→ * The trie uses sparse children (sorted {@code edges[]} + parallel {@code children[]}) for space
 20→ * efficiency with binary search on edges at each node.
 21→ */
 22→public final class KeyIndex {
 23→
 24→    /** A key-offset pair produced during iteration. */
 25→    public record Entry(MemorySegment key, long fileOffset) {
 26→    }
 27→
 28→    // --- Trie node types ---
 29→
 30→    private sealed interface TrieNode permits Inner, Leaf {
 31→    }
 32→
 33→    private record Leaf(long fileOffset) implements TrieNode {
 34→    }
 35→
 36→    private static final class Inner implements TrieNode {
 37→        byte[] edges; // sorted (unsigned) byte values of outgoing edges
 38→        TrieNode[] children; // parallel with edges
 39→        long fileOffset; // -1L if this node is not terminal
 40→
 41→        Inner() {
 42→            this.edges = new byte[0];
 43→            this.children = new TrieNode[0];
 44→            this.fileOffset = -1L;
 45→        }
 46→
 47→        TrieNode get(byte b) {
 48→            int idx = binarySearch(b);
 49→            return idx >= 0 ? children[idx] : null;
 50→        }
 51→
 52→        void put(byte b, TrieNode child) {
 53→            int idx = binarySearch(b);
 54→            if (idx >= 0) {
 55→                children[idx] = child;
 56→            } else {
 57→                int ins = -(idx + 1);
 58→                byte[] newEdges = new byte[edges.length + 1];
 59→                TrieNode[] newChildren = new TrieNode[children.length + 1];
 60→                System.arraycopy(edges, 0, newEdges, 0, ins);
 61→                System.arraycopy(children, 0, newChildren, 0, ins);
 62→                newEdges[ins] = b;
 63→                newChildren[ins] = child;
 64→                System.arraycopy(edges, ins, newEdges, ins + 1, edges.length - ins);
 65→                System.arraycopy(children, ins, newChildren, ins + 1, children.length - ins);
 66→                edges = newEdges;
 67→                children = newChildren;
 68→            }
 69→        }
 70→
 71→        private int binarySearch(byte b) {
 72→            int unsignedB = b & 0xFF;
 73→            int lo = 0, hi = edges.length - 1;
 74→            while (lo <= hi) {
 75→                int mid = (lo + hi) >>> 1;
 76→                int midVal = edges[mid] & 0xFF;
 77→                if (midVal == unsignedB)
 78→                    return mid;
 79→                if (midVal < unsignedB)
 80→                    lo = mid + 1;
 81→                else
 82→                    hi = mid - 1;
 83→            }
 84→            return -(lo + 1);
 85→        }
 86→    }
 87→
 88→    private final Inner root;
 89→
 90→    /**
 91→     * Constructs a {@code KeyIndex} from parallel sorted lists of keys and file offsets.
 92→     *
 93→     * @param keys sorted list of unique keys; must not be null
 94→     * @param offsets parallel list of file offsets; same size as keys
 95→     */
 96→    public KeyIndex(List<MemorySegment> keys, List<Long> offsets) {
 97→        Objects.requireNonNull(keys, "keys must not be null");
 98→        Objects.requireNonNull(offsets, "offsets must not be null");
 99→        assert keys.size() == offsets.size() : "keys and offsets must have the same size";
100→        this.root = new Inner();
101→        for (int i = 0; i < keys.size(); i++) {
102→            insert(keys.get(i), offsets.get(i));
103→        }
104→    }
105→
106→    private void insert(MemorySegment key, long offset) {
107→        assert key != null : "key must not be null";
108→        byte[] bytes = key.toArray(ValueLayout.JAVA_BYTE);
109→
110→        if (bytes.length == 0) {
111→            root.fileOffset = offset;
112→            return;
113→        }
114→
115→        Inner current = root;
116→        for (int d = 0; d < bytes.length - 1; d++) {
117→            byte b = bytes[d];
118→            TrieNode child = current.get(b);
119→            if (child == null) {
120→                Inner next = new Inner();
121→                current.put(b, next);
122→                current = next;
123→            } else if (child instanceof Inner inner) {
124→                current = inner;
125→            } else {
126→                // Leaf at intermediate position — promote to Inner
127→                Leaf leaf = (Leaf) child;
128→                Inner next = new Inner();
129→                next.fileOffset = leaf.fileOffset();
130→                current.put(b, next);
131→                current = next;
132→            }
133→        }
134→
135→        // Last byte
136→        byte lastByte = bytes[bytes.length - 1];
137→        TrieNode existing = current.get(lastByte);
138→        if (existing == null) {
139→            current.put(lastByte, new Leaf(offset));
140→        } else if (existing instanceof Inner inner) {
141→            inner.fileOffset = offset;
142→        } else {
143→            // Replace leaf
144→            current.put(lastByte, new Leaf(offset));
145→        }
146→    }
147→
148→    /**
149→     * Looks up the file offset for an exact key match.
150→     *
151→     * @param key the key to search for; must not be null
152→     * @return the file offset, or empty if not found
153→     */
154→    public Optional<Long> lookup(MemorySegment key) {
155→        Objects.requireNonNull(key, "key must not be null");
156→        byte[] bytes = key.toArray(ValueLayout.JAVA_BYTE);
157→
158→        if (bytes.length == 0) {
159→            return root.fileOffset >= 0 ? Optional.of(root.fileOffset) : Optional.empty();
160→        }
161→
162→        Inner current = root;
163→        for (int d = 0; d < bytes.length - 1; d++) {
164→            TrieNode child = current.get(bytes[d]);
165→            if (child == null)
166→                return Optional.empty();
167→            switch (child) {
168→                case Leaf _ -> {
169→                    return Optional.empty();
170→                }
171→                case Inner inner -> current = inner;
172→            }
173→        }
174→
175→        TrieNode last = current.get(bytes[bytes.length - 1]);
176→        if (last == null)
177→            return Optional.empty();
178→        return switch (last) {
179→            case Leaf leaf -> Optional.of(leaf.fileOffset());
180→            case Inner inner ->
181→                inner.fileOffset >= 0 ? Optional.of(inner.fileOffset) : Optional.empty();
182→        };
183→    }
184→
185→    /** Returns an in-order iterator over all (key, offset) pairs. */
186→    public Iterator<Entry> iterator() {
187→        List<Entry> result = new ArrayList<>();
188→        dfs(root, new byte[0], result, null, null);
189→        return result.iterator();
190→    }
191→
192→    /**
193→     * Returns an iterator over entries whose keys fall in {@code [from, to)}.
194→     *
195→     * @param from inclusive lower bound; must not be null
196→     * @param to exclusive upper bound; must not be null
197→     */
198→    public Iterator<Entry> rangeIterator(MemorySegment from, MemorySegment to) {
199→        Objects.requireNonNull(from, "from must not be null");
200→        Objects.requireNonNull(to, "to must not be null");
201→        byte[] fromBytes = from.toArray(ValueLayout.JAVA_BYTE);
202→        byte[] toBytes = to.toArray(ValueLayout.JAVA_BYTE);
203→        List<Entry> result = new ArrayList<>();
204→        dfs(root, new byte[0], result, fromBytes, toBytes);
205→        return result.iterator();
206→    }
207→
208→    /** Typed stack frame for the iterative DFS. */
209→    private record Frame(TrieNode node, byte[] prefix) {
210→    }
211→
212→    /**
213→     * DFS in sorted edge order, collecting entries in [fromKey, toKey). Iterative implementation.
214→     */
215→    private static void dfs(TrieNode startNode, byte[] startPrefix, List<Entry> result,
216→            byte[] fromKey, byte[] toKey) {
217→        Deque<Frame> stack = new ArrayDeque<>();
218→        stack.push(new Frame(startNode, startPrefix));
219→
220→        while (!stack.isEmpty()) {
221→            Frame frame = stack.pop();
222→            TrieNode node = frame.node();
223→            byte[] prefix = frame.prefix();
224→
225→            switch (node) {
226→                case Leaf leaf -> {
227→                    if (inRange(prefix, fromKey, toKey)) {
228→                        result.add(new Entry(MemorySegment.ofArray(prefix), leaf.fileOffset()));
229→                    }
230→                }
231→                case Inner inner -> {
232→                    // Check terminal
233→                    if (inner.fileOffset >= 0 && inRange(prefix, fromKey, toKey)) {
234→                        result.add(new Entry(MemorySegment.ofArray(prefix), inner.fileOffset));
235→                    }
236→                    // Push children in REVERSE order so leftmost child is processed first (LIFO).
237→                    // Determine the last index to push: find the rightmost edge where childPrefix
238→                    // is still < toKey (edges are sorted ascending, so prune from the right).
239→                    int lastValid = inner.edges.length - 1;
240→                    if (toKey != null) {
241→                        while (lastValid >= 0) {
242→                            byte[] childPrefix = Arrays.copyOf(prefix, prefix.length + 1);
243→                            childPrefix[prefix.length] = inner.edges[lastValid];
244→                            if (compareUnsigned(childPrefix, toKey) < 0)
245→                                break;
246→                            lastValid--;
247→                        }
248→                    }
249→                    for (int i = lastValid; i >= 0; i--) {
250→                        byte[] childPrefix = Arrays.copyOf(prefix, prefix.length + 1);
251→                        childPrefix[prefix.length] = inner.edges[i];
252→                        stack.push(new Frame(inner.children[i], childPrefix));
253→                    }
254→                }
255→            }
256→        }
257→    }
258→
259→    private static boolean inRange(byte[] key, byte[] fromKey, byte[] toKey) {
260→        if (fromKey != null && compareUnsigned(key, fromKey) < 0)
261→            return false;
262→        if (toKey != null && compareUnsigned(key, toKey) >= 0)
263→            return false;
264→        return true;
265→    }
266→
267→    static int compareUnsigned(byte[] a, byte[] b) {
268→        int len = Math.min(a.length, b.length);
269→        for (int i = 0; i < len; i++) {
270→            int cmp = Byte.compareUnsigned(a[i], b[i]);
271→            if (cmp != 0)
272→                return cmp;
273→        }
274→        return Integer.compare(a.length, b.length);
275→    }
276→}
