 26→/**
 27→ * WAL implementation for network/object storage backends.
 28→ *
 29→ * <p>
 30→ * Each {@link #append} writes exactly one record into a brand-new immutable segment file named
 31→ * {@code wal-{seqnum:016d}.log}. Files are written once via a single positioned write and never
 32→ * modified afterwards. No mmap is used for writes.
 33→ *
 34→ * <p>
 35→ * Recovery is O(1): the highest sequence number is inferred from the lexicographically largest file
 36→ * name — no record scanning required.
 37→ */
 38→public final class RemoteWriteAheadLog implements WriteAheadLog {
 39→
 40→    private static final long DEFAULT_READ_BUFFER_SIZE = 16L * 1024 * 1024; // 16 MiB
 41→    private static final int DEFAULT_POOL_SIZE = 4;
 42→    private static final long DEFAULT_BUFFER_SIZE = 1024 * 1024L; // 1 MiB for writes
 43→    private static final long DEFAULT_ACQUIRE_TIMEOUT_MILLIS = 10_000L;
 44→
 45→    private final Path directory;
 46→    private final long readBufferSize;
 47→    private final ArenaBufferPool bufferPool;
 48→    private final ReentrantLock writeLock = new ReentrantLock();
 49→    private final AtomicLong nextSequence = new AtomicLong(1L);
 50→
 51→    private RemoteWriteAheadLog(Path directory, long readBufferSize, ArenaBufferPool bufferPool,
 52→            long initialNextSequence) {
 53→        assert directory != null : "directory must not be null";
 54→        assert readBufferSize > 0 : "readBufferSize must be positive";
 55→        assert bufferPool != null : "bufferPool must not be null";
 56→
 57→        this.directory = directory;
 58→        this.readBufferSize = readBufferSize;
 59→        this.bufferPool = bufferPool;
 60→        this.nextSequence.set(initialNextSequence);
 61→    }
 62→
 63→    // -------------------------------------------------------------------------
 64→    // WriteAheadLog interface
 65→    // -------------------------------------------------------------------------
 66→
 67→    @Override
 68→    public SequenceNumber append(Entry entry) throws IOException {
 69→        Objects.requireNonNull(entry, "entry must not be null");
 70→
 71→        writeLock.lock();
 72→        try {
 73→            long seq = nextSequence.getAndIncrement();
 74→            Entry stamped = stamp(entry, new SequenceNumber(seq));
 75→
 76→            MemorySegment buf = bufferPool.acquire();
 77→            try {
 78→                int n = WalRecord.encode(stamped, buf);
 79→                Path target = directory.resolve(SegmentFile.toFileName(seq));
 80→
 81→                try (SeekableByteChannel ch = Files.newByteChannel(target,
 82→                        StandardOpenOption.CREATE_NEW, StandardOpenOption.WRITE)) {
 83→                    ByteBuffer bb = buf.asByteBuffer().limit(n);
 84→                    while (bb.hasRemaining()) {
 85→                        ch.write(bb);
 86→                    }
 87→                    if (ch instanceof java.nio.channels.FileChannel fc)
 88→                        fc.force(false);
 89→                }
 90→                return new SequenceNumber(seq);
 91→            } finally {
 92→                bufferPool.release(buf);
 93→            }
 94→        } finally {
 95→            writeLock.unlock();
 96→        }
 97→    }
 98→
 99→    @Override
100→    public Iterator<Entry> replay(SequenceNumber from) throws IOException {
101→        Objects.requireNonNull(from, "from must not be null");
102→
103→        List<Path> all = SegmentFile.listSorted(directory);
104→        if (all.isEmpty())
105→            return Collections.emptyIterator();
106→
107→        // Filter to files with encoded seqnum >= from.value()
108→        List<Path> filtered = new ArrayList<>();
109→        for (Path p : all) {
110→            long seqNum = SegmentFile.parseNumber(p.getFileName().toString());
111→            if (seqNum >= from.value())
112→                filtered.add(p);
113→        }
114→
115→        return new ReplayIterator(filtered, readBufferSize);
116→    }
117→
118→    @Override
119→    public void truncateBefore(SequenceNumber upTo) throws IOException {
120→        Objects.requireNonNull(upTo, "upTo must not be null");
121→
122→        List<Path> all = SegmentFile.listSorted(directory);
123→        for (Path p : all) {
124→            long seqNum = SegmentFile.parseNumber(p.getFileName().toString());
125→            if (seqNum < upTo.value()) {
126→                java.nio.file.Files.deleteIfExists(p);
127→            }
128→        }
129→    }
130→
131→    @Override
132→    public SequenceNumber lastSequenceNumber() throws IOException {
133→        long next = nextSequence.get();
134→        if (next <= 1L)
135→            return SequenceNumber.ZERO;
136→        return new SequenceNumber(next - 1L);
137→    }
138→
139→    @Override
140→    public void close() throws IOException {
141→        bufferPool.close();
142→    }
143→
144→    // -------------------------------------------------------------------------
145→    // Helpers
146→    // -------------------------------------------------------------------------
147→
148→    private static Entry stamp(Entry entry, SequenceNumber seq) {
149→        return switch (entry) {
150→            case Entry.Put put -> new Entry.Put(put.key(), put.value(), seq);
151→            case Entry.Delete del -> new Entry.Delete(del.key(), seq);
152→        };
153→    }
154→
155→    // -------------------------------------------------------------------------
156→    // Replay iterator
157→    // -------------------------------------------------------------------------
158→
159→    private static final class ReplayIterator implements Iterator<Entry> {
160→
161→        private final List<Path> segments;
162→        private final long readBufferSize;
163→        private int segIdx = 0;
164→        private Entry next;
165→
166→        ReplayIterator(List<Path> segments, long readBufferSize) {
167→            this.segments = segments;
168→            this.readBufferSize = readBufferSize;
169→            advance();
170→        }
171→
172→        private void advance() {
173→            next = null;
174→            while (next == null && segIdx < segments.size()) {
175→                Path path = segments.get(segIdx++);
176→                next = readRecord(path);
177→            }
178→        }
179→
180→        private Entry readRecord(Path path) {
181→            try {
182→                long fileSize = java.nio.file.Files.size(path);
183→                if (fileSize == 0)
184→                    return null;
185→
186→                try (SeekableByteChannel ch = Files.newByteChannel(path, StandardOpenOption.READ)) {
187→                    long readSize = Math.min(fileSize, readBufferSize);
188→                    ByteBuffer bb = ByteBuffer.allocate((int) readSize);
189→                    while (bb.hasRemaining()) {
190→                        if (ch.read(bb) < 0)
191→                            break;
192→                    }
193→                    bb.flip();
194→                    MemorySegment seg = MemorySegment.ofBuffer(bb);
195→                    try {
196→                        return WalRecord.decode(seg, 0, bb.limit());
197→                    } catch (IOException e) {
198→                        // Partial or corrupt record — skip silently
199→                        return null;
200→                    }
201→                }
202→            } catch (IOException e) {
203→                throw new UncheckedIOException(e);
204→            }
205→        }
206→
207→        @Override
208→        public boolean hasNext() {
209→            return next != null;
210→        }
211→
212→        @Override
213→        public Entry next() {
214→            if (next == null)
215→                throw new NoSuchElementException();
216→            Entry result = next;
217→            advance();
218→            return result;
219→        }
220→    }
221→
222→    // -------------------------------------------------------------------------
223→    // Builder
224→    // -------------------------------------------------------------------------
225→
226→    public static Builder builder() {
227→        return new Builder();
228→    }
229→
230→    public static final class Builder {
231→        private Path directory;
232→        private long readBufferSize = DEFAULT_READ_BUFFER_SIZE;
233→        private int poolSize = DEFAULT_POOL_SIZE;
234→        private long bufferSize = DEFAULT_BUFFER_SIZE;
235→        private long acquireTimeoutMillis = DEFAULT_ACQUIRE_TIMEOUT_MILLIS;
236→
237→        public Builder directory(Path directory) {
238→            Objects.requireNonNull(directory, "directory must not be null");
239→            this.directory = directory;
240→            return this;
241→        }
242→
243→        public Builder readBufferSize(long readBufferSize) {
244→            if (readBufferSize < 1)
245→                throw new IllegalArgumentException("readBufferSize must be >= 1");
246→            this.readBufferSize = readBufferSize;
247→            return this;
248→        }
249→
250→        public Builder poolSize(int poolSize) {
251→            if (poolSize < 1)
252→                throw new IllegalArgumentException("poolSize must be >= 1");
253→            this.poolSize = poolSize;
254→            return this;
255→        }
256→
257→        public Builder bufferSize(long bufferSize) {
258→            if (bufferSize < 1)
259→                throw new IllegalArgumentException("bufferSize must be >= 1");
260→            this.bufferSize = bufferSize;
261→            return this;
262→        }
263→
264→        public Builder acquireTimeoutMillis(long millis) {
265→            if (millis <= 0)
266→                throw new IllegalArgumentException("acquireTimeoutMillis must be > 0");
267→            this.acquireTimeoutMillis = millis;
268→            return this;
269→        }
270→
271→        public RemoteWriteAheadLog build() throws IOException {
272→            Objects.requireNonNull(directory, "directory must not be null");
273→
274→            // Recovery: find max seqnum from file names
275→            List<Path> existing = SegmentFile.listSorted(directory);
276→            long initialNext = 1L;
277→            if (!existing.isEmpty()) {
278→                Path last = existing.get(existing.size() - 1);
279→                long maxSeq = SegmentFile.parseNumber(last.getFileName().toString());
280→                assert maxSeq >= 0 : "invalid segment file found during recovery";
281→                initialNext = maxSeq + 1L;
282→            }
283→
284→            ArenaBufferPool pool = ArenaBufferPool.builder().poolSize(poolSize)
285→                    .bufferSize(bufferSize).acquireTimeoutMillis(acquireTimeoutMillis).build();
286→            return new RemoteWriteAheadLog(directory, readBufferSize, pool, initialNext);
287→        }
288→    }
289→}
