  8→import java.util.concurrent.TimeUnit;
  9→
 10→/**
 11→ * Off-heap buffer pool backed by a shared {@link Arena}. Segments are pre-allocated at construction
 12→ * and returned to the pool via {@link #release}. Shared across WAL and compaction.
 13→ */
 14→public final class ArenaBufferPool implements AutoCloseable {
 15→
 16→    private final Arena arena;
 17→    private final LinkedBlockingQueue<MemorySegment> queue;
 18→    private final long acquireTimeoutNanos;
 19→    private volatile boolean closed = false;
 20→
 21→    private ArenaBufferPool(int poolSize, long bufferSize, long acquireTimeoutMillis) {
 22→        assert poolSize >= 1 : "poolSize must be >= 1";
 23→        assert bufferSize >= 1 : "bufferSize must be >= 1";
 24→        assert acquireTimeoutMillis > 0 : "acquireTimeoutMillis must be > 0";
 25→
 26→        this.arena = Arena.ofShared();
 27→        this.acquireTimeoutNanos = TimeUnit.MILLISECONDS.toNanos(acquireTimeoutMillis);
 28→        this.queue = new LinkedBlockingQueue<>(poolSize);
 29→        for (int i = 0; i < poolSize; i++) {
 30→            boolean offered = queue.offer(arena.allocate(bufferSize, 8));
 31→            assert offered : "queue must accept all pre-allocated segments";
 32→        }
 33→    }
 34→
 35→    /**
 36→     * Acquires a segment from the pool, blocking up to the configured timeout.
 37→     *
 38→     * @throws IOException if the pool is exhausted or the thread is interrupted
 39→     */
 40→    public MemorySegment acquire() throws IOException {
 41→        try {
 42→            MemorySegment seg = queue.poll(acquireTimeoutNanos, TimeUnit.NANOSECONDS);
 43→            if (seg == null) {
 44→                throw new IOException("buffer pool exhausted");
 45→            }
 46→            return seg;
 47→        } catch (InterruptedException e) {
 48→            Thread.currentThread().interrupt();
 49→            throw new IOException("interrupted while waiting for buffer", e);
 50→        }
 51→    }
 52→
 53→    /**
 54→     * Returns a segment to the pool.
 55→     *
 56→     * @param segment must not be null; must have been obtained from this pool
 57→     */
 58→    public void release(MemorySegment segment) {
 59→        Objects.requireNonNull(segment, "segment must not be null");
 60→        boolean offered = queue.offer(segment);
 61→        assert offered : "release should always succeed — pool capacity invariant violated";
 62→    }
 63→
 64→    /**
 65→     * Closes the underlying {@link Arena}. Idempotent.
 66→     */
 67→    @Override
 68→    public void close() {
 69→        if (!closed) {
 70→            closed = true;
 71→            arena.close();
 72→        }
 73→    }
 74→
 75→    public static Builder builder() {
 76→        return new Builder();
 77→    }
 78→
 79→    public static final class Builder {
 80→        private int poolSize = -1;
 81→        private long bufferSize = -1;
 82→        private long acquireTimeoutMillis = -1;
 83→
 84→        public Builder poolSize(int poolSize) {
 85→            if (poolSize < 1) {
 86→                throw new IllegalArgumentException("poolSize must be >= 1, got: " + poolSize);
 87→            }
 88→            this.poolSize = poolSize;
 89→            return this;
 90→        }
 91→
 92→        public Builder bufferSize(long bufferSize) {
 93→            if (bufferSize < 1) {
 94→                throw new IllegalArgumentException("bufferSize must be >= 1, got: " + bufferSize);
 95→            }
 96→            this.bufferSize = bufferSize;
 97→            return this;
 98→        }
 99→
100→        public Builder acquireTimeoutMillis(long acquireTimeoutMillis) {
101→            if (acquireTimeoutMillis <= 0) {
102→                throw new IllegalArgumentException(
103→                        "acquireTimeoutMillis must be > 0, got: " + acquireTimeoutMillis);
104→            }
105→            this.acquireTimeoutMillis = acquireTimeoutMillis;
106→            return this;
107→        }
108→
109→        public ArenaBufferPool build() {
110→            if (poolSize < 1)
111→                throw new IllegalStateException("poolSize must be configured");
112→            if (bufferSize < 1)
113→                throw new IllegalStateException("bufferSize must be configured");
114→            if (acquireTimeoutMillis <= 0)
115→                throw new IllegalStateException("acquireTimeoutMillis must be configured");
116→            return new ArenaBufferPool(poolSize, bufferSize, acquireTimeoutMillis);
117→        }
118→    }
119→}
